-- =============================================================================
-- 473 — LE CAHIER D'EXERCICES DE 5E (partie 2)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/5e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 473 --niveau 5e --fichiers anglais.n3,anglais.n4,arts-plastiques.n1,emc.jumelles --suffixe 2 > supabase/contenu/473_exercices_5e_2.sql
--
-- 96 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   anglais.n3              33 exercices · 11 chapitres
--   anglais.n4              24 exercices · 8 chapitres
--   arts-plastiques.n1       9 exercices · 3 chapitres
--   emc.jumelles            30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('9be9b70b-6d29-5be3-ad11-8f8a571d6523'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Que faisais-tu à huit heures ?","competence":"comprendre-langue","situation":"Emma a appelé Tom hier soir sans réponse. Le lendemain, ils se racontent leur soirée par messages.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages d’Emma et Tom","participants":[{"nom":"Emma","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Emma","texte":"Where were you at eight o’clock last night? I called you."},{"qui":"Tom","texte":"Sorry! I was watching a film with my sister."},{"qui":"Emma","texte":"No problem. I was doing my homework."},{"qui":"Tom","texte":"We were eating pizza, too!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes** en **-ING** qui disent ce que chacun était en train de faire.","aide":"Cherche les verbes qui se terminent par -ing.","type":"zone","document":"sms","multiple":true},{"enonce":"Complète avec l’auxiliaire qui convient.","aide":"Le sujet est pluriel (Tom et sa sœur) et la scène se passe hier soir.","type":"trous","segments":["Last night at eight, Tom and his sister ",0," eating pizza."],"banque":["do","was","were","are"]},{"enonce":"Que faisait Emma à huit heures ?","aide":"Relis la réponse d’Emma à Tom.","type":"choix","options":[{"id":"a","texte":"Elle mangeait une pizza."},{"id":"b","texte":"Elle regardait un film."},{"id":"c","texte":"Elle téléphonait à sa mère."},{"id":"d","texte":"Elle faisait ses devoirs."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14","m24","m29"]},"explication":"**watching**, **doing** et **eating** : was / were + verbe en **-ING** dit une action en cours à un moment du passé."},{"cle":{"type":"trous","trous":[["were"]]},"affichage":"were","explication":"**were** : sujet pluriel au passé, donc **were** + verbe en -ING."},{"cle":{"type":"choix","ids":["d"]},"explication":"Emma dit « I was doing my homework » : à huit heures, elle **faisait ses devoirs**."}]$ex$::jsonb),
  ('9be9b70b-6d29-5be3-ad11-8f8a571d6523'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un témoin chez la police","competence":"analyser-document","situation":"Un témoin raconte à la police ce qu’il a vu devant un magasin. Il décrit d’abord ce qu’il faisait, puis ce qui s’est passé.","documents":[{"id":"temoin","type":"texte","genre":"article","titre":"Witness statement","blocs":["I was walking my dog in Park Road at nine when I heard a loud noise.","While I was crossing the street, a man ran out of the shop. He was carrying a big bag."],"source":"Témoignage écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes** qui disent ce qui **survient** et interrompt le témoin (verbes au prétérit simple).","aide":"Ces actions sont courtes et soudaines.","type":"zone","document":"temoin","multiple":true},{"enonce":"Range chaque verbe du témoignage : **décor** de la scène ou **événement** qui survient ?","aide":"Le décor dure ; l’événement interrompt.","type":"categories","categories":[{"id":"c0","texte":"Le décor (BE + -ING)"},{"id":"c1","texte":"L’événement (prétérit simple)"}],"items":[{"id":"i0","texte":"was carrying"},{"id":"i1","texte":"was crossing"},{"id":"i2","texte":"was walking"},{"id":"i3","texte":"ran out"},{"id":"i4","texte":"heard"}]},{"enonce":"Complète avec le verbe qui convient.","aide":"L’événement qui interrompt est une action courte.","type":"trous","segments":["I was walking my dog when I ",0," a noise."],"banque":["hearing","was hearing","hear","heard"]},{"enonce":"Remets en ordre : « Pendant que je traversais la rue, un homme est sorti en courant. » La phrase commence par While.","aide":"Le décor en -ING vient avant l’événement.","type":"ordre","items":[{"id":"a","texte":"was crossing"},{"id":"b","texte":"the street,"},{"id":"c","texte":"a man"},{"id":"d","texte":"ran out"},{"id":"e","texte":"While I"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12","m24"]},"explication":"**heard** et **ran** : l’événement qui survient est au prétérit simple."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c0","i3":"c1","i4":"c1"}},"explication":"Le **décor** (action longue) est en **BE + -ING** ; l’**événement** (action courte) est au prétérit simple."},{"cle":{"type":"trous","trous":[["heard"]]},"affichage":"heard","explication":"**heard** : l’action courte qui survient se met au prétérit simple."},{"cle":{"type":"ordre","ids":["e","a","b","c","d"]},"explication":"**While I was crossing the street, a man ran out** : *while* + décor en BE + -ING, puis l’événement."}]$ex$::jsonb),
  ('9be9b70b-6d29-5be3-ad11-8f8a571d6523'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La panne de courant","competence":"argumenter","situation":"Ben raconte à sa cousine Zoe la soirée où le courant s’est coupé. Elle lui répond avec une anecdote semblable.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Ben’s message","blocs":["Hi Zoe, guess what happened last night! At half past seven we were having dinner when the lights went out.","Dad was cooking pasta, Mum was setting the table and I was chatting with Luke online. While we were looking for candles, our dog was barking like crazy. Then the lights came back. Love, Ben"],"source":"Message écrit pour l’exercice"},{"id":"zoe","type":"dialogue","modele":"sms","titre":"Réponse de Zoe","participants":[{"nom":"Zoe","emoji":"👩","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Zoe","texte":"That’s funny! Last week my brother was playing a video game when the power went off."},{"qui":"Zoe","texte":"He was shouting at the TV while I was laughing."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui dit **ce qui a interrompu** le dîner de la famille.","aide":"Cherche l’action courte, au prétérit simple.","type":"zone","document":"mail","multiple":false},{"enonce":"Associe chaque personne à ce qu’elle faisait quand les lumières se sont éteintes.","aide":"Relis le message de Ben, phrase par phrase.","type":"association","gauche":[{"id":"g0","texte":"Dad"},{"id":"g1","texte":"Mum"},{"id":"g2","texte":"Ben"},{"id":"g3","texte":"The dog"}],"droite":[{"id":"d0","texte":"was chatting online"},{"id":"d1","texte":"was setting the table"},{"id":"d2","texte":"was cooking pasta"},{"id":"d3","texte":"was barking"}]},{"enonce":"Dans le message de Zoe, touche les **deux verbes** de la phrase avec *while* : deux actions **simultanées**.","aide":"Les deux actions se passent en même temps.","type":"zone","document":"zoe","multiple":true},{"enonce":"Quelles phrases sont **correctes** ? (deux bonnes réponses)","aide":"Un verbe d’état n’accepte pas -ING, et il faut was / were devant le verbe en -ING.","type":"choix","options":[{"id":"a","texte":"The dog was barking while we were looking for candles."},{"id":"b","texte":"I was knowing where the candles were."},{"id":"c","texte":"We were eating when the lights went out."},{"id":"d","texte":"While the lights were going out, we eating pasta."}],"multiple":true},{"enonce":"Complète avec le bon verbe.","aide":"C’est l’événement qui interrompt la partie.","type":"trous","segments":["Zoe’s brother was playing a game when the power ",0," off."],"banque":["was going","gone","goes","went"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"**went** : « the lights went out » est l’événement qui interrompt le dîner (action en cours)."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"Chacun était **en train de** faire une action : le décor est en **was / were + -ING**."},{"cle":{"type":"zone","ids":["m18","m25"]},"explication":"**shouting** et **laughing** : *while* relie deux actions simultanées, toutes deux en BE + -ING."},{"cle":{"type":"choix","ids":["a","c"]},"explication":"Les phrases 1 et 3 sont correctes. « I was knowing » est faux (**know** est un verbe d’état) et la dernière oublie **were**."},{"cle":{"type":"trous","trous":[["went"]]},"affichage":"went","explication":"**went** : l’événement qui survient est au prétérit simple (*the power went off*)."}]$ex$::jsonb),
  ('46244cfd-d0c6-5842-9ffa-3decc7d0c6b1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Prêt pour le départ ?","competence":"comprendre-langue","situation":"Léo part en voyage scolaire demain. Sa mère lui envoie des messages pour vérifier qu’il est prêt.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Maman et Léo","participants":[{"nom":"Mum","emoji":"👩","cote":"gauche"},{"nom":"Leo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mum","texte":"Have you packed your bag yet?"},{"qui":"Leo","texte":"Yes, I’ve already packed it. I’ve just finished my homework, but I haven’t found my passport."},{"qui":"Mum","texte":"Have you looked in the drawer?"},{"qui":"Leo","texte":"Not yet!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux marqueurs** placés entre *have* et le participe passé dans la réponse de Léo.","aide":"Un marqueur de temps se glisse entre l’auxiliaire et le participe.","type":"zone","document":"sms","multiple":true},{"enonce":"Complète avec l’auxiliaire qui convient.","aide":"Léo est une troisième personne du singulier.","type":"trous","segments":["Leo ",0," already packed his bag."],"banque":["have","has","did","is"]},{"enonce":"Léo a-t-il retrouvé son passeport ?","aide":"Cherche la phrase négative de Léo.","type":"choix","options":[{"id":"a","texte":"Non, il ne l’a pas encore retrouvé."},{"id":"b","texte":"Oui, il l’a retrouvé dans le tiroir."},{"id":"c","texte":"On ne sait rien : il n’en parle pas."},{"id":"d","texte":"Oui, il l’a retrouvé ce matin."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m12"]},"explication":"**already** et **just** se placent entre l’auxiliaire et le participe passé : *I’ve already packed*, *I’ve just finished*."},{"cle":{"type":"trous","trous":[["has"]]},"affichage":"has","explication":"**has** : le present perfect se forme avec **have / has** + participe passé, et *Leo* prend **has**."},{"cle":{"type":"choix","ids":["a"]},"explication":"« I haven’t found my passport » : il **ne l’a pas encore retrouvé**."}]$ex$::jsonb),
  ('46244cfd-d0c6-5842-9ffa-3decc7d0c6b1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Depuis quand, pendant combien de temps ?","competence":"manier-langue","situation":"Le club de loisirs du collège présente ses membres. Chacun dit depuis combien de temps il pratique son activité.","documents":[{"id":"club","type":"tableau","titre":"Les membres du club","colonnes":["Member","Activity","Since / for"],"lignes":[["Amy","play the piano","for four years"],["Ravi","study French","since September"],["Lena","live in Dover","since she was six"],["Sam","have a dog","for two months"]],"enteteLignes":false,"source":"Informations écrites pour l’exercice"}],"questions":[{"enonce":"Touche les **deux cases** qui donnent une **durée** (une quantité de temps).","aide":"Une durée répond à « pendant combien de temps ? ».","type":"zone","document":"club","multiple":true},{"enonce":"Complète avec **since** ou **for**.","aide":"Septembre est un point de départ ; deux mois est une durée.","type":"trous","segments":["Ravi has studied French ",0," September, and Sam has had his dog ",1," two months."],"banque":["for","since","in","ago"]},{"enonce":"Quelle phrase est correcte ?","aide":"Il faut un point de départ après *since*, et le present perfect.","type":"choix","options":[{"id":"a","texte":"Lena has lived in Dover since she was six."},{"id":"b","texte":"Lena lives in Dover since she was six."},{"id":"c","texte":"Lena has lived in Dover for she was six."},{"id":"d","texte":"Lena has lived in Dover since six years."}],"multiple":false},{"enonce":"Range chaque expression : **for** ou **since** ?","aide":"For : combien de temps. Since : à partir de quand.","type":"categories","categories":[{"id":"c0","texte":"for"},{"id":"c1","texte":"since"}],"items":[{"id":"i0","texte":"I was ten"},{"id":"i1","texte":"two hours"},{"id":"i2","texte":"three weeks"},{"id":"i3","texte":"a long time"},{"id":"i4","texte":"2020"},{"id":"i5","texte":"Monday"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2","r3c2"]},"explication":"**for four years** et **for two months** sont des durées : on emploie **for** devant une durée."},{"cle":{"type":"trous","trous":[["since"],["for"]]},"affichage":"since · for","explication":"**since** devant un point de départ (*since September*) et **for** devant une durée (*for two months*). **ago** et **in** sont impossibles avec le present perfect."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Lena has lived in Dover since she was six** : *since* + point de départ, avec **have / has** + participe passé."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c0","i4":"c1","i5":"c1"}},"explication":"**For** + durée (two hours, a long time, three weeks) ; **since** + point de départ (Monday, 2020, I was ten)."}]$ex$::jsonb),
  ('46244cfd-d0c6-5842-9ffa-3decc7d0c6b1'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une lettre du Japon","competence":"argumenter","situation":"Emily voyage à Tokyo avec sa famille. Elle écrit à sa grand-mère, qui lui répond ensuite par message.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Dear Gran","blocs":["Dear Gran, we arrived in Tokyo on Monday, so we have been here for four days. I have already tried sushi!","Yesterday we visited a big castle. I have never seen such a huge city before. Love, Emily"],"source":"Lettre écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Gran et Emily","participants":[{"nom":"Gran","emoji":"👵","cote":"gauche"},{"nom":"Emily","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Gran","texte":"Have you visited Kyoto yet?"},{"qui":"Emily","texte":"No, I have never been there. We are going next week!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes au prétérit** : ils sont accompagnés d’un repère de date précis.","aide":"Cherche *on Monday* et *yesterday*.","type":"zone","document":"lettre","multiple":true},{"enonce":"Pourquoi Emily écrit-elle « we visited a castle yesterday » et non « we have visited a castle yesterday » ?","aide":"Quel mot situe l’action à une date précise ?","type":"choix","options":[{"id":"a","texte":"Parce que *visit* ne se met jamais au present perfect."},{"id":"b","texte":"Parce que *yesterday* est un repère passé précis."},{"id":"c","texte":"Parce que le château est loin d’elle maintenant."},{"id":"d","texte":"Parce que le present perfect est réservé aux verbes irréguliers."}],"multiple":false},{"enonce":"Range chaque phrase : **present perfect** ou **prétérit** ?","aide":"Une date précise appelle le prétérit.","type":"categories","categories":[{"id":"c0","texte":"Present perfect"},{"id":"c1","texte":"Prétérit"}],"items":[{"id":"i0","texte":"I have tried sushi."},{"id":"i1","texte":"She saw it last week."},{"id":"i2","texte":"I’ve never been to Kyoto."},{"id":"i3","texte":"We arrived on Monday."},{"id":"i4","texte":"We went there yesterday."},{"id":"i5","texte":"We have been here for four days."}]},{"enonce":"Remets en ordre : « Elle est à Tokyo depuis lundi. » La phrase commence par She.","aide":"Commence par have / has + participe passé.","type":"ordre","items":[{"id":"a","texte":"Monday"},{"id":"b","texte":"has"},{"id":"c","texte":"in Tokyo"},{"id":"d","texte":"since"},{"id":"e","texte":"been"},{"id":"f","texte":"She"}]},{"enonce":"Dans les messages, touche le marqueur d’**expérience** qui veut dire « jamais ».","aide":"Il se place entre have et le participe passé.","type":"zone","document":"sms","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m23"]},"explication":"**arrived** (on Monday) et **visited** (yesterday) sont au prétérit : une date précise interdit le present perfect."},{"cle":{"type":"choix","ids":["b"]},"explication":"Avec **yesterday**, le fait est coupé du présent : on emploie le **prétérit**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c1","i5":"c0"}},"explication":"Le **present perfect** n’a pas de date et garde un lien avec le présent ; le **prétérit** accepte *on Monday*, *yesterday*, *last week*."},{"cle":{"type":"ordre","ids":["f","b","e","c","d","a"]},"explication":"**She has been in Tokyo since Monday** : *has been* + *since* + point de départ."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**never** : *I have never been there* dit qu’Emily n’a jamais vécu cette expérience."}]$ex$::jsonb),
  ('4e207dd7-f3ec-5d24-a5e2-a222e57211ef'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le train de Mia","competence":"comprendre-langue","situation":"Mia arrive à la gare pour aller chez sa tante, mais la journée ne se passe pas comme prévu.","documents":[{"id":"gare","type":"texte","genre":"recit","titre":"At the station","blocs":["When Mia arrived at the station, the train had already left. She was sad because she had missed it.","She had also forgotten her phone at home."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois participes passés** qui suivent *had* dans le texte.","aide":"Ils décrivent ce qui s’était passé avant l’arrivée de Mia.","type":"zone","document":"gare","multiple":true},{"enonce":"Complète avec l’auxiliaire qui convient.","aide":"C’est l’auxiliaire du past perfect, le même à toutes les personnes.","type":"trous","segments":["When Mia arrived, the train ",0," already left."],"banque":["had","was","has","did"]},{"enonce":"Quelle action s’est passée **en premier** ?","aide":"Cherche l’action au past perfect.","type":"choix","options":[{"id":"a","texte":"Mia a été triste."},{"id":"b","texte":"Mia a parlé au contrôleur."},{"id":"c","texte":"Mia est arrivée à la gare."},{"id":"d","texte":"Le train est parti."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m17","m22"]},"explication":"**left**, **missed** et **forgotten** suivent *had* : le past perfect se forme avec **had + participe passé**."},{"cle":{"type":"trous","trous":[["had"]]},"affichage":"had","explication":"**had** : le train était parti **avant** l’arrivée de Mia."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le **train** était déjà parti quand Mia est arrivée : l’action au past perfect est la plus ancienne."}]$ex$::jsonb),
  ('4e207dd7-f3ec-5d24-a5e2-a222e57211ef'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"En retard à l’école","competence":"lire-tableau","situation":"Lola est arrivée en retard à l’école. Elle explique à son professeur ce qui s’est passé, heure par heure. Elle est allée à l’école à pied.","documents":[{"id":"matin","type":"tableau","titre":"Le matin de Lola","colonnes":["Time","What happened"],"lignes":[["07.40","The bus left the stop."],["07.45","Lola arrived at the stop."],["08.30","The lessons started."],["08.40","Lola got to school."]],"enteteLignes":false,"source":"Emploi du temps écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case de l’action la **plus ancienne** de la matinée.","aide":"Compare les heures.","type":"zone","document":"matin","multiple":false},{"enonce":"Complète avec l’auxiliaire qui convient.","aide":"Le bus est parti à 7 h 40, avant Lola.","type":"trous","segments":["When Lola arrived at the stop, the bus ",0," already left."],"banque":["has","was","had","have"]},{"enonce":"Remets en ordre : « Le bus était parti avant que Lola arrive. » La phrase commence par The bus.","aide":"L’action la plus ancienne est au past perfect.","type":"ordre","items":[{"id":"a","texte":"Lola"},{"id":"b","texte":"arrived"},{"id":"c","texte":"before"},{"id":"d","texte":"The bus"},{"id":"e","texte":"had"},{"id":"f","texte":"left"}]},{"enonce":"Range chaque morceau : action **la plus ancienne** (past perfect) ou **la plus récente** (prétérit) ?","aide":"Pour chaque couple, regarde l’heure qui vient d’abord dans le tableau.","type":"categories","categories":[{"id":"c0","texte":"La plus ancienne (past perfect)"},{"id":"c1","texte":"La plus récente (prétérit)"}],"items":[{"id":"i0","texte":"Lola got to school"},{"id":"i1","texte":"the bus had left"},{"id":"i2","texte":"Lola arrived at the stop"},{"id":"i3","texte":"the lessons had started"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"**The bus left the stop** à 7 h 40 : c’est la première action, donc celle qu’on met au past perfect."},{"cle":{"type":"trous","trous":[["had"]]},"affichage":"had","explication":"**had** : le past perfect (**had + left**) pose le départ du bus **avant** l’arrivée de Lola."},{"cle":{"type":"ordre","ids":["d","e","f","c","a","b"]},"explication":"**The bus had left before Lola arrived** : *had left* est antérieur à *arrived*."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Au moment où Lola arrive, **le bus était parti** et **les cours avaient commencé** : ce sont les actions les plus anciennes."}]$ex$::jsonb),
  ('4e207dd7-f3ec-5d24-a5e2-a222e57211ef'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le regret de Nathan","competence":"argumenter","situation":"Nathan a raté un contrôle. Il raconte sa journée dans son journal, puis discute avec sa mère par messages.","documents":[{"id":"journal","type":"texte","genre":"recit","titre":"Nathan’s diary","blocs":["Last Friday was terrible. I had stayed up late the night before, so I overslept.","When I got to school, the teacher looked at me and said, “You arrived too late.” I wish I had gone to bed earlier! If I had set my alarm, I would have arrived on time."],"source":"Journal écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Nathan et Maman","participants":[{"nom":"Nathan","emoji":"👦","cote":"gauche"},{"nom":"Mum","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Nathan","texte":"I’d studied all week, but I overslept."},{"qui":"Mum","texte":"Oh dear. I’d like to call your teacher."},{"qui":"Nathan","texte":"Please don’t! I’d rather write to her myself."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui introduit le **regret** de Nathan sur le passé.","aide":"Ce mot est suivi d’un past perfect.","type":"zone","document":"journal","multiple":false},{"enonce":"Que signifie « If I had set my alarm, I would have arrived on time » ?","aide":"La troisième condition parle de ce qui ne s’est pas passé.","type":"choix","options":[{"id":"a","texte":"Il a réglé son réveil et il est arrivé à l’heure."},{"id":"b","texte":"Il n’a pas réglé son réveil et il est arrivé en retard."},{"id":"c","texte":"Il n’a pas réglé son réveil, mais il est arrivé à l’heure."},{"id":"d","texte":"Il réglera son réveil pour arriver à l’heure."}],"multiple":false},{"enonce":"Complète pour rapporter les paroles du professeur.","aide":"Au discours indirect, le prétérit devient un past perfect.","type":"trous","segments":["The teacher said that I ",0," arrived too late."],"banque":["would","has","had","was"]},{"enonce":"Remets en ordre : « S’il avait pris le bus, il serait arrivé plus tôt. » La phrase commence par If he.","aide":"Past perfect dans le *if*, would have + participe dans la principale.","type":"ordre","items":[{"id":"a","texte":"have arrived"},{"id":"b","texte":"If he"},{"id":"c","texte":"earlier"},{"id":"d","texte":"had taken"},{"id":"e","texte":"he would"},{"id":"f","texte":"the bus,"}]},{"enonce":"Dans les messages, ’d vaut-il **had** ou **would** ?","aide":"Après ’d, regarde si le mot suivant est un participe passé.","type":"categories","categories":[{"id":"c0","texte":"’d = had"},{"id":"c1","texte":"’d = would"}],"items":[{"id":"i0","texte":"I’d like"},{"id":"i1","texte":"I’d rather"},{"id":"i2","texte":"I’d studied"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m32"]},"explication":"**wish** + past perfect exprime un regret sur le passé : *I wish I had gone to bed earlier*."},{"cle":{"type":"choix","ids":["b"]},"explication":"**if + past perfect, would have + participe passé** : l’irréel du passé. Les faits réels sont l’inverse."},{"cle":{"type":"trous","trous":[["had"]]},"affichage":"had","explication":"Après **said**, le prétérit (*arrived*) devient **had arrived** au discours indirect."},{"cle":{"type":"ordre","ids":["b","d","f","e","a","c"]},"explication":"**If he had taken the bus, he would have arrived earlier** : troisième condition."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0"}},"explication":"**I’d studied** = *I had studied* (participe passé). **I’d like** et **I’d rather** = *I would like / would rather*."}]$ex$::jsonb),
  ('5bf23e62-b833-599e-a78a-f76019c10ed0'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les projets du week-end","competence":"comprendre-langue","situation":"Ana et Ben parlent de leur samedi par messages. Chacun a des projets, mais pas de la même façon.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages d’Ana et Ben","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"It’s Saturday tomorrow! What are you doing?"},{"qui":"Ben","texte":"I’m meeting Sam at the cinema at three."},{"qui":"Ana","texte":"Nice! I’m going to tidy my room in the morning."},{"qui":"Ben","texte":"Oh no! I’ll come and help you!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la forme qui annonce une **décision prise sur le moment**.","aide":"Elle est très courte et se contracte avec le pronom.","type":"zone","document":"sms","multiple":false},{"enonce":"Range chaque phrase selon la façon d’envisager l’avenir.","aide":"Plus c’est préparé, plus on s’éloigne de will.","type":"categories","categories":[{"id":"c0","texte":"Rendez-vous organisé"},{"id":"c1","texte":"Intention déjà formée"},{"id":"c2","texte":"Décision immédiate"}],"items":[{"id":"i0","texte":"I’m going to tidy my room."},{"id":"i1","texte":"I’ll come and help you!"},{"id":"i2","texte":"I’m meeting Sam at the cinema at three."}]},{"enonce":"Pourquoi Ben dit-il « I’m meeting Sam at the cinema at three » ?","aide":"Regarde ce que Ben précise : où et quand.","type":"choix","options":[{"id":"a","texte":"Parce que c’est un horaire officiel."},{"id":"b","texte":"Parce qu’il fait une promesse à Sam."},{"id":"c","texte":"Parce qu’il vient de décider de voir Sam."},{"id":"d","texte":"Parce que le rendez-vous est organisé."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27"]},"explication":"**I’ll** (= *I will*) exprime une décision prise au moment de parler : Ben propose son aide sur-le-champ."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c0"}},"explication":"**BE + -ING** pour un rendez-vous organisé, **be going to** pour une intention, **will** pour une décision prise à l’instant."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le **présent en BE + -ING** exprime un **rendez-vous organisé**, avec lieu et heure."}]$ex$::jsonb),
  ('5bf23e62-b833-599e-a78a-f76019c10ed0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le train pour Oxford","competence":"lire-tableau","situation":"Léo et sa mère vont à Oxford en train. Ils regardent le tableau des horaires puis échangent quelques messages.","documents":[{"id":"gare","type":"tableau","titre":"Horaires de la gare","colonnes":["Destination","Leaves","Arrives"],"lignes":[["Bath","09.40","10.35"],["Bristol","10.05","11.00"],["Oxford","10.30","11.25"]],"enteteLignes":false,"source":"Horaires inventés pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Maman et Léo","participants":[{"nom":"Mum","emoji":"👩","cote":"gauche"},{"nom":"Leo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mum","texte":"The train leaves at 10.30, so we must hurry."},{"qui":"Leo","texte":"I’m meeting Jack at the station at ten, remember?"},{"qui":"Mum","texte":"I’m going to buy a sandwich first."},{"qui":"Leo","texte":"I’ll carry your bag!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Léo va à Oxford. Touche l’**heure de départ** de son train.","aide":"Trouve d’abord la ligne d’Oxford, puis la colonne *Leaves*.","type":"zone","document":"gare","multiple":false},{"enonce":"Complète avec la forme qui convient pour un **horaire officiel**.","aide":"Un horaire officiel se dit au présent simple.","type":"trous","segments":["The train to Bristol ",0," at 10.05."],"banque":["leaves","is leaving","will leave","leave"]},{"enonce":"Complète après la conjonction de temps.","aide":"Après *as soon as*, l’anglais emploie le présent.","type":"trous","segments":["I’ll call you as soon as the train ",0," in Oxford."],"banque":["arriving","arrives","will arrive","arrived"]},{"enonce":"Associe chaque phrase des messages à ce qu’elle exprime.","aide":"Demande-toi à quel point la chose est préparée.","type":"association","gauche":[{"id":"g0","texte":"The train leaves at 10.30."},{"id":"g1","texte":"I’m meeting Jack at ten."},{"id":"g2","texte":"I’m going to buy a sandwich."},{"id":"g3","texte":"I’ll carry your bag!"}],"droite":[{"id":"d0","texte":"horaire officiel"},{"id":"d1","texte":"intention"},{"id":"d2","texte":"décision immédiate"},{"id":"d3","texte":"rendez-vous organisé"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Le train d’Oxford part à **10.30** : c’est la case de la ligne *Oxford*, colonne *Leaves*."},{"cle":{"type":"trous","trous":[["leaves"]]},"affichage":"leaves","explication":"**leaves** : on emploie le **présent simple** pour un horaire officiel."},{"cle":{"type":"trous","trous":[["arrives"]]},"affichage":"arrives","explication":"**arrives** : après *as soon as*, on emploie le **présent**, jamais *will*."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"**Présent simple** pour l’horaire, **BE + -ING** pour le rendez-vous, **be going to** pour l’intention, **will** pour la décision immédiate."}]$ex$::jsonb),
  ('5bf23e62-b833-599e-a78a-f76019c10ed0'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le camp de la classe","competence":"argumenter","situation":"La classe de Jade part en camp au pays de Galles. Elle lit l’avis de la prof et échange avec sa mère.","documents":[{"id":"avis","type":"texte","genre":"article","titre":"Camp notice","blocs":["Our class is going to visit Wales next month. The coach leaves at 7.30 on Monday.","Mrs Hart is meeting the parents at the gate at seven. As soon as we arrive, we will unpack. Before we go to bed, we will tell stories."],"source":"Avis écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Jade et Maman","participants":[{"nom":"Jade","emoji":"👧","cote":"gauche"},{"nom":"Mum","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Jade","texte":"I was going to pack last night, but I fell asleep."},{"qui":"Mum","texte":"Don’t worry. I’ll help you now."},{"qui":"Jade","texte":"Thanks! It’s going to rain, so I’ll take my coat."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le verbe au **présent simple** qui donne un **horaire officiel**.","aide":"Cherche l’heure de départ du car.","type":"zone","document":"avis","multiple":false},{"enonce":"Pourquoi écrit-on « As soon as we arrive » et pas « As soon as we will arrive » ?","aide":"Regarde le temps du verbe après la conjonction de temps.","type":"choix","options":[{"id":"a","texte":"Parce que *arrive* est un verbe irrégulier."},{"id":"b","texte":"Parce que le car part déjà."},{"id":"c","texte":"Parce qu’après *as soon as*, on emploie le présent."},{"id":"d","texte":"Parce que *will* est réservé aux promesses."}],"multiple":false},{"enonce":"Dans les messages de Jade, range chaque phrase.","aide":"Chaque forme a son sens : passé, sur le moment, indice visible.","type":"categories","categories":[{"id":"c0","texte":"Intention passée (was going to)"},{"id":"c1","texte":"Décision immédiate (will)"},{"id":"c2","texte":"Prédiction fondée sur un indice (be going to)"}],"items":[{"id":"i0","texte":"It’s going to rain."},{"id":"i1","texte":"I’ll help you now."},{"id":"i2","texte":"I’ll take my coat."},{"id":"i3","texte":"I was going to pack last night."}]},{"enonce":"Remets en ordre : « Avant d’aller nous coucher, nous raconterons des histoires. » La phrase commence par Before.","aide":"Après *before*, on emploie le présent.","type":"ordre","items":[{"id":"a","texte":"go"},{"id":"b","texte":"Before"},{"id":"c","texte":"we will"},{"id":"d","texte":"to bed,"},{"id":"e","texte":"tell stories"},{"id":"f","texte":"we"}]},{"enonce":"Complète avec la forme qui convient.","aide":"Après la conjonction de temps, le présent.","type":"trous","segments":["As soon as the coach ",0,", Mrs Hart will call the parents."],"banque":["will stop","stops","stopped","is stopping"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"**leaves** : le présent simple donne l’horaire officiel du car."},{"cle":{"type":"choix","ids":["c"]},"explication":"Après **as soon as**, **when**, **before**, **after** et **until**, l’anglais emploie le **présent**, pas *will*."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c1","i3":"c0"}},"explication":"**was going to** = j’avais l’intention ; **will** = décision sur le moment ; **be going to** = prédiction d’après un indice."},{"cle":{"type":"ordre","ids":["b","f","a","d","c","e"]},"explication":"**Before we go to bed, we will tell stories** : présent après *before*, *will* dans la principale."},{"cle":{"type":"trous","trous":[["stops"]]},"affichage":"stops","explication":"**stops** : le présent suit *as soon as*, même pour parler de l’avenir."}]$ex$::jsonb),
  ('6729549c-84de-5b94-a173-23caf85f21f6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Si j’avais un chien","competence":"comprendre-langue","situation":"Lina et Max discutent de la météo de demain, puis Lina rêve à voix haute.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Lina et Max","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Max","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"If it rains tomorrow, I will stay home."},{"qui":"Max","texte":"Me too. If it’s sunny, I will go to the park."},{"qui":"Lina","texte":"If I had a dog, I would take it to the park."},{"qui":"Max","texte":"You don’t have a dog!"},{"qui":"Lina","texte":"No, but if I had one, I would call him Bingo."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui montrent que Lina parle de quelque chose d’**irréel**.","aide":"Ils se trouvent dans la proposition principale, pas après *if*.","type":"zone","document":"sms","multiple":true},{"enonce":"Range chaque phrase : condition **possible** (type 1) ou **irréelle** (type 2) ?","aide":"Lina a-t-elle vraiment un chien ?","type":"categories","categories":[{"id":"c0","texte":"Type 1 : possible"},{"id":"c1","texte":"Type 2 : irréel du présent"}],"items":[{"id":"i0","texte":"If it’s sunny, I will go to the park."},{"id":"i1","texte":"If I had one, I would call him Bingo."},{"id":"i2","texte":"If I had a dog, I would take it to the park."},{"id":"i3","texte":"If it rains tomorrow, I will stay home."}]},{"enonce":"Complète pour une condition irréelle.","aide":"On n’a pas de vélo : le verbe après *if* est au prétérit.","type":"trous","segments":["If I ",0," a bike, I would ride to school."],"banque":["had","would have","have","will have"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m25","m43"]},"explication":"**would** (deux fois) : *if + prétérit, would + base verbale* exprime l’irréel du présent."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"Type 1 : *if + présent, will*. Type 2 : *if + prétérit, would*, pour une situation irréelle."},{"cle":{"type":"trous","trous":[["had"]]},"affichage":"had","explication":"**had** : *if + prétérit*, jamais *will* ni *would* après *if*."}]$ex$::jsonb),
  ('6729549c-84de-5b94-a173-23caf85f21f6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre à la directrice","competence":"argumenter","situation":"Zoe a mis un mot dans la boîte à idées du collège : elle explique ce qu’elle ferait si elle dirigeait l’établissement.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Dear Mrs Bell","blocs":["Dear Mrs Bell, if I were the head teacher, I would build a swimming pool. If we had a pool, we would swim every Friday.","I would also change the canteen: if it served pizza, more students would eat there. Thank you for reading! Zoe, class 5B"],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui est à la forme **were** après *if I*.","aide":"Il remplace *was* dans cette structure.","type":"zone","document":"lettre","multiple":false},{"enonce":"Complète avec la bonne forme.","aide":"On emploie la même forme pour toutes les personnes.","type":"trous","segments":["If I ",0," you, I would apologise."],"banque":["be","were","am","will be"]},{"enonce":"Associe chaque condition de la lettre à sa conséquence.","aide":"Relis chaque phrase de Zoe.","type":"association","gauche":[{"id":"g0","texte":"If we had a pool,"},{"id":"g1","texte":"If the canteen served pizza,"},{"id":"g2","texte":"If I were the head teacher,"}],"droite":[{"id":"d0","texte":"more students would eat there."},{"id":"d1","texte":"I would build a swimming pool."},{"id":"d2","texte":"we would swim every Friday."}]},{"enonce":"Remets en ordre : « S’il pleuvait, nous jouerions à l’intérieur. » La phrase commence par If it.","aide":"Prétérit après *if*, would + base verbale dans la principale.","type":"ordre","items":[{"id":"a","texte":"play"},{"id":"b","texte":"we would"},{"id":"c","texte":"inside"},{"id":"d","texte":"rained,"},{"id":"e","texte":"If it"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5"]},"explication":"**were** : dans la condition de type 2, on emploie **were** à toutes les personnes (*if I were…*)."},{"cle":{"type":"trous","trous":[["were"]]},"affichage":"were","explication":"**were** : *If I were you, I would…* est la forme à retenir."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**if + prétérit, would + base verbale** : chaque condition irréelle est suivie de sa conséquence."},{"cle":{"type":"ordre","ids":["e","d","b","a","c"]},"explication":"**If it rained, we would play inside** : type 2, avec une virgule après la proposition en *if*."}]$ex$::jsonb),
  ('6729549c-84de-5b94-a173-23caf85f21f6'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le bus manqué d’Ellie","competence":"argumenter","situation":"Ellie a raté la sortie scolaire. Le journal du collège raconte l’histoire, puis ses camarades réagissent.","documents":[{"id":"journal","type":"texte","genre":"article","titre":"School news","blocs":["Ellie missed the museum trip last Saturday. She says: “If I had gone to bed earlier, I would have caught the bus.”","Next time, if she sets two alarms, she will arrive on time."],"source":"Article écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de la classe","participants":[{"nom":"Sam","emoji":"👦","cote":"gauche"},{"nom":"Ruby","emoji":"👧","cote":"droite"},{"nom":"Ellie","emoji":"👩","cote":"gauche"}],"repliques":[{"qui":"Sam","texte":"If you had told me, I would have woken you up."},{"qui":"Ruby","texte":"If you come with us next time, you will love the museum."},{"qui":"Ellie","texte":"If I had a car, I would drive to the museum myself!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Dans la proposition en *if* d’Ellie, touche les **deux mots** qui forment le past perfect.","aide":"Cherche *had* et le participe passé qui le suit.","type":"zone","document":"journal","multiple":true},{"enonce":"Que signifie « If I had gone to bed earlier, I would have caught the bus » ?","aide":"Une condition de type 3 parle du contraire de ce qui s’est passé.","type":"choix","options":[{"id":"a","texte":"Ellie s’est couchée tôt et elle a pris le bus."},{"id":"b","texte":"Ellie ne se couche jamais tôt et prend toujours le bus."},{"id":"c","texte":"Ellie ne se couchera pas tôt demain."},{"id":"d","texte":"Ellie ne s’est pas couchée tôt et elle a manqué le bus."}],"multiple":false},{"enonce":"Range chaque phrase selon son **type** de condition.","aide":"Regarde le temps du verbe après *if*.","type":"categories","categories":[{"id":"c0","texte":"Type 1 (possible)"},{"id":"c1","texte":"Type 2 (irréel du présent)"},{"id":"c2","texte":"Type 3 (irréel du passé)"}],"items":[{"id":"i0","texte":"If I had gone to bed earlier, I would have caught the bus."},{"id":"i1","texte":"If you had told me, I would have woken you up."},{"id":"i2","texte":"If I had a car, I would drive to the museum myself!"},{"id":"i3","texte":"If you come with us next time, you will love the museum."}]},{"enonce":"Complète pour une condition possible.","aide":"Condition de type 1 : présent après *if*.","type":"trous","segments":["Next time, if Ellie ",0," two alarms, she will arrive on time."],"banque":["would set","sets","set","will set"]},{"enonce":"Remets en ordre : « Si j’avais su, je te l’aurais dit. » La phrase commence par If I.","aide":"Past perfect après *if*, would have + participe dans la principale.","type":"ordre","items":[{"id":"a","texte":"I would"},{"id":"b","texte":"had known,"},{"id":"c","texte":"you"},{"id":"d","texte":"have told"},{"id":"e","texte":"If I"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11","m12"]},"explication":"**had** et **gone** : *if + past perfect* exprime un regret sur le passé."},{"cle":{"type":"choix","ids":["d"]},"explication":"Type 3 : **if + past perfect, would have + participe passé**. Les faits réels sont l’inverse."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c2","i2":"c1","i3":"c0"}},"explication":"Présent → type 1 ; prétérit → type 2 ; past perfect → type 3."},{"cle":{"type":"trous","trous":[["sets"]]},"affichage":"sets","explication":"**sets** : après *if*, on emploie le **présent** pour une condition possible."},{"cle":{"type":"ordre","ids":["e","b","a","d","c"]},"explication":"**If I had known, I would have told you** : troisième condition."}]$ex$::jsonb),
  ('f800b423-7b52-5226-8464-46379032ec41'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Dimanche au parc","competence":"comprendre-langue","situation":"Max raconte son dimanche dans son carnet. Certains verbes sont irréguliers, d’autres suivent la règle du -ed.","documents":[{"id":"carnet","type":"texte","genre":"recit","titre":"Max’s notebook","blocs":["Last Sunday, I got up late, ate pancakes and went to the park.","I played football and saw my cousin there. We bought ice cream and watched the ducks."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **cinq verbes irréguliers** au prétérit.","aide":"Les verbes réguliers se terminent par -ed.","type":"zone","document":"carnet","multiple":true},{"enonce":"Associe chaque verbe à son prétérit.","aide":"Pense à la deuxième colonne de la liste.","type":"association","gauche":[{"id":"g0","texte":"go"},{"id":"g1","texte":"see"},{"id":"g2","texte":"buy"},{"id":"g3","texte":"eat"}],"droite":[{"id":"d0","texte":"bought"},{"id":"d1","texte":"ate"},{"id":"d2","texte":"saw"},{"id":"d3","texte":"went"}]},{"enonce":"Complète après *didn’t*.","aide":"Après *did* ou *didn’t*, on emploie la base verbale.","type":"trous","segments":["I didn’t ",0," pancakes yesterday."],"banque":["ate","eaten","eat","eating"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m6","m9","m17","m22"]},"explication":"**got, ate, went, saw, bought** sont irréguliers ; **played** et **watched** suivent la règle du -ed."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g1":"d2","g0":"d3"}},"explication":"go – **went**, see – **saw**, buy – **bought**, eat – **ate**."},{"cle":{"type":"trous","trous":[["eat"]]},"affichage":"eat","explication":"**eat** : après **didn’t**, on emploie la **première colonne** (base verbale)."}]$ex$::jsonb),
  ('f800b423-7b52-5226-8464-46379032ec41'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le tableau des trois formes","competence":"lire-tableau","situation":"Pour réviser, Lena complète un tableau de verbes irréguliers. Il manque quelques formes.","documents":[{"id":"verbes","type":"tableau","titre":"Les trois formes","colonnes":["Base","Past","Past participle"],"lignes":[["write","wrote","?"],["drink","?","drunk"],["buy","bought","?"],["take","?","taken"],["speak","spoke","?"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Complète la case violette de la ligne **write** : le participe passé.","aide":"Pense à *I have …* devant le verbe.","type":"texte","placeholder":"Participe passé"},{"enonce":"Complète la case violette de la ligne **drink** : le prétérit.","aide":"Le prétérit est la deuxième colonne.","type":"texte","placeholder":"Prétérit"},{"enonce":"Complète avec les bonnes formes.","aide":"Après *has*, on emploie la troisième colonne.","type":"trous","segments":["Lena has ",0," a letter and she has ",1," a glass of water."],"banque":["drunk","written","drank","wrote"]},{"enonce":"Range chaque verbe selon sa famille.","aide":"Compare les trois colonnes : cut – cut – cut ; buy – bought – bought ; take – took – taken.","type":"categories","categories":[{"id":"c0","texte":"Trois formes identiques"},{"id":"c1","texte":"Prétérit = participe passé"},{"id":"c2","texte":"Trois formes différentes"}],"items":[{"id":"i0","texte":"think"},{"id":"i1","texte":"write"},{"id":"i2","texte":"cut"},{"id":"i3","texte":"put"},{"id":"i4","texte":"take"},{"id":"i5","texte":"buy"}]}]}$ex$::jsonb,
