  ('f800b423-7b52-5226-8464-46379032ec41'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une semaine en Cornouailles","competence":"argumenter","situation":"Ivy est en vacances en Cornouailles. Elle écrit à son grand-père, qui lui répond par message.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Dear Grandpa","blocs":["Dear Grandpa, we have had a wonderful week in Cornwall. I have swum in the sea every day, and I have eaten fish and chips three times!","Yesterday we flew kites on the beach and Dad broke his sunglasses. I have written five postcards. Love, Ivy"],"source":"Lettre écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Grand-père et Ivy","participants":[{"nom":"Grandpa","emoji":"👴","cote":"gauche"},{"nom":"Ivy","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Grandpa","texte":"Did you buy any stamps?"},{"qui":"Ivy","texte":"No, I didn’t buy any. The shop was closed."},{"qui":"Grandpa","texte":"Have you taken any photos?"},{"qui":"Ivy","texte":"Yes, I have taken fifty!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes au prétérit** (hier).","aide":"Ils sont à la deuxième colonne de la liste.","type":"zone","document":"lettre","multiple":true},{"enonce":"Range chaque verbe de la lettre : **prétérit** (colonne 2) ou **participe passé** (colonne 3) ?","aide":"Les participes passés suivent *have* ou *has*.","type":"categories","categories":[{"id":"c0","texte":"Prétérit (colonne 2)"},{"id":"c1","texte":"Participe passé (colonne 3)"}],"items":[{"id":"i0","texte":"flew"},{"id":"i1","texte":"broke"},{"id":"i2","texte":"written"},{"id":"i3","texte":"eaten"},{"id":"i4","texte":"swum"}]},{"enonce":"Touche le verbe qui suit *didn’t* dans la réponse d’Ivy.","aide":"Après *didn’t*, on emploie la première colonne.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète avec la bonne forme.","aide":"Après *has*, on emploie la troisième colonne.","type":"trous","segments":["Ivy has ",0," fifty photos."],"banque":["took","taken","taking","take"]},{"enonce":"Remets en ordre : « Je n’ai jamais vu la mer. » La phrase commence par I.","aide":"*never* se place entre l’auxiliaire et le participe passé.","type":"ordre","items":[{"id":"a","texte":"have"},{"id":"b","texte":"never"},{"id":"c","texte":"seen"},{"id":"d","texte":"I"},{"id":"e","texte":"the sea"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29","m36"]},"explication":"**flew** et **broke** sont au prétérit (colonne 2) : fly – flew – flown, break – broke – broken."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c1"}},"explication":"**flew, broke** sont des prétérits ; **swum, eaten, written** suivent *have* : ce sont des participes passés."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**buy** : après *didn’t*, on emploie la **base verbale**, pas *bought*."},{"cle":{"type":"trous","trous":[["taken"]]},"affichage":"taken","explication":"**taken** : *has taken*, avec le participe passé (take – took – taken)."},{"cle":{"type":"ordre","ids":["d","a","b","c","e"]},"explication":"**I have never seen the sea** : *see – saw – seen*, et *never* se place entre *have* et le participe."}]$ex$::jsonb),
  ('c35d5f08-6d70-5be4-bf01-ccaa86897c0b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un téléphone tout neuf","competence":"comprendre-langue","situation":"Léa raconte à une amie l’achat de son téléphone. L’ordre des mots anglais est strict : sujet, verbe, complément.","documents":[{"id":"texte","type":"texte","genre":"recit","titre":"Léa’s weekend","blocs":["Last Saturday I bought a new phone in town. It was raining, so I took a taxi.","There is a problem now: my sister borrowed it."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le **nom** qui est le complément d’objet de *bought*.","aide":"Qu’est-ce que Léa a acheté ?","type":"zone","document":"texte","multiple":false},{"enonce":"Remets en ordre : « Elle a joué du piano magnifiquement au concert hier soir. » La phrase commence par She.","aide":"Après l’objet : manière, lieu, temps.","type":"ordre","items":[{"id":"a","texte":"She"},{"id":"b","texte":"the piano"},{"id":"c","texte":"at the concert"},{"id":"d","texte":"beautifully"},{"id":"e","texte":"played"},{"id":"f","texte":"last night"}]},{"enonce":"Pourquoi écrit-on « It was raining » et non « Was raining » ?","aide":"Regarde la phrase sans *it* : que manque-t-il ?","type":"choix","options":[{"id":"a","texte":"Parce que le sujet est obligatoire en anglais."},{"id":"b","texte":"Parce que le prétérit exige *it*."},{"id":"c","texte":"Parce que *rain* est un verbe irrégulier."},{"id":"d","texte":"Parce que *raining* est un nom."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"**phone** : *I (S) bought (V) a new phone (O)* suit l’ordre sujet – verbe – objet."},{"cle":{"type":"ordre","ids":["a","e","b","d","c","f"]},"explication":"**She played the piano beautifully at the concert last night** : sujet, verbe, objet, puis manière → lieu → temps."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le **sujet est obligatoire** en anglais, même quand il est vide : *It was raining*."}]$ex$::jsonb),
  ('c35d5f08-6d70-5be4-bf01-ccaa86897c0b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La soirée de Lou","competence":"manier-langue","situation":"Lou raconte sa soirée dans un petit article. Il y a des phrases coordonnées et des phrases subordonnées.","documents":[{"id":"soiree","type":"texte","genre":"article","titre":"Lou’s evening","blocs":["I was tired, so I went to bed early. I wanted to read, but my eyes hurt.","My sister, who sleeps in the next room, was playing music that I don’t like. I will tell her when she comes home."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots de coordination** qui relient deux propositions de même rang.","aide":"Ce sont des petits mots entre deux propositions.","type":"zone","document":"soiree","multiple":true},{"enonce":"Range chaque mot du texte : **coordination** ou **subordination** ?","aide":"La subordination fait dépendre une proposition d’une autre.","type":"categories","categories":[{"id":"c0","texte":"Coordination"},{"id":"c1","texte":"Subordination"}],"items":[{"id":"i0","texte":"but"},{"id":"i1","texte":"so"},{"id":"i2","texte":"when"},{"id":"i3","texte":"who"}]},{"enonce":"Complète après la conjonction de temps.","aide":"Après *as soon as*, on emploie le présent.","type":"trous","segments":["I’ll call you as soon as I ",0," home."],"banque":["will get","get","getting","got"]},{"enonce":"Remets en ordre : « Je n’ai vu personne. » La phrase commence par I.","aide":"Une seule négation par phrase.","type":"ordre","items":[{"id":"a","texte":"anybody"},{"id":"b","texte":"I"},{"id":"c","texte":"see"},{"id":"d","texte":"didn’t"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m13"]},"explication":"**so** et **but** coordonnent deux propositions : elles ont le **même rang**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"**so, but** relient deux propositions de même rang ; **who** (relative) et **when** (temps) introduisent une subordonnée."},{"cle":{"type":"trous","trous":[["get"]]},"affichage":"get","explication":"**get** : après une conjonction de temps, on emploie le **présent** pour l’avenir."},{"cle":{"type":"ordre","ids":["b","d","c","a"]},"explication":"**I didn’t see anybody** : l’anglais n’admet pas de double négation (*nobody*)."}]$ex$::jsonb),
  ('c35d5f08-6d70-5be4-bf01-ccaa86897c0b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le club d’échecs","competence":"argumenter","situation":"Noor et Ali découvrent le club d’échecs du collège. Ils lisent le règlement, puis échangent des messages.","documents":[{"id":"club","type":"texte","genre":"article","titre":"Chess club","blocs":["Our chess club meets on Fridays at four o’clock. You can bring a friend if you ask Mr Hall first.","Unless it rains, we play in the yard. We use the library when it is cold. In order to win more games, practise every week."],"source":"Règlement écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Noor et Ali","participants":[{"nom":"Noor","emoji":"👧","cote":"gauche"},{"nom":"Ali","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Noor","texte":"I speak English well, but I didn’t understand the rules."},{"qui":"Ali","texte":"I think they are simple. I often play with my brother."},{"qui":"Noor","texte":"I will call you when I arrive on Friday."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la conjonction qui veut dire « **à moins que** ».","aide":"C’est le premier mot d’une phrase du règlement.","type":"zone","document":"club","multiple":false},{"enonce":"Range chaque morceau du règlement selon le **type** de subordonnée.","aide":"Pense à la question : quand ? sous quelle condition ? pour quoi ?","type":"categories","categories":[{"id":"c0","texte":"Temps"},{"id":"c1","texte":"Condition"},{"id":"c2","texte":"But"}],"items":[{"id":"i0","texte":"when it is cold"},{"id":"i1","texte":"unless it rains"},{"id":"i2","texte":"if you ask Mr Hall first"},{"id":"i3","texte":"in order to win more games"}]},{"enonce":"Complète le mot omis.","aide":"C’est un mot qu’on peut souvent omettre après *I think*.","type":"trous","segments":["I think ",0," they are simple."],"banque":["that","which","who","where"]},{"enonce":"Touche l’**adverbe de fréquence** dans les messages.","aide":"Il répond à « à quelle fréquence ? ».","type":"zone","document":"sms","multiple":false},{"enonce":"Quelle phrase est correcte ?","aide":"Une seule négation, et la base verbale après *didn’t*.","type":"choix","options":[{"id":"a","texte":"We didn’t meet anyone at the club."},{"id":"b","texte":"We met not anyone at the club."},{"id":"c","texte":"We didn’t met anyone at the club."},{"id":"d","texte":"We didn’t meet no one at the club."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m20"]},"explication":"**Unless** exprime une condition négative (« à moins que »)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c2"}},"explication":"**when** : temps ; **if, unless** : condition ; **in order to** : but."},{"cle":{"type":"trous","trous":[["that"]]},"affichage":"that","explication":"**that** introduit la subordonnée complétive ; il est souvent omis dans « I think they are simple »."},{"cle":{"type":"zone","ids":["m16"]},"explication":"**often** se place **avant** le verbe lexical : *I often play*."},{"cle":{"type":"choix","ids":["a"]},"explication":"**We didn’t meet anyone** : pas de double négation, base verbale après *didn’t*."}]$ex$::jsonb),
