   $ex${"titre":"Le téléphone perdu","competence":"comprendre-langue","situation":"Jo a perdu son téléphone au collège. Sam l’aide à le retrouver.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Jo et Sam","participants":[{"nom":"Jo","emoji":"👧","cote":"gauche"},{"nom":"Sam","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Jo","texte":"I can’t find my phone. Can you help me?"},{"qui":"Sam","texte":"Sure! Is this blue phone yours?"},{"qui":"Jo","texte":"No, mine is red. That one is Lily’s. She lost it yesterday."},{"qui":"Sam","texte":"I’ll give it to her at school."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le **pronom complément** qui remplace *Lily*.","aide":"Un pronom complément suit le verbe ou une préposition.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète avec le pronom possessif.","aide":"Il remplace « mon téléphone » sans nom derrière.","type":"trous","segments":["No, ",0," is red."],"banque":["mine","my","myself","me"]},{"enonce":"Que remplace *it* dans « She lost it yesterday » ?","aide":"Relis la phrase d’avant : *That one is Lily’s*.","type":"choix","options":[{"id":"a","texte":"Lily elle-même."},{"id":"b","texte":"Le collège."},{"id":"c","texte":"Le téléphone de Jo."},{"id":"d","texte":"Le téléphone de Lily."}],"multiple":false}]}$ex$::jsonb,
