  ('b5de6f27-974a-50e9-b102-160316cc7b1f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Merci pour la fête","competence":"manier-langue","situation":"Après l’anniversaire d’Emma, une amie lui écrit une carte de remerciement. Emma lui répond par message.","documents":[{"id":"carte","type":"texte","genre":"lettre","titre":"Dear Emma","blocs":["Dear Emma, we had a great time at your party. Tom himself made a joke, and my brother made the cake himself!","We want to thank you and your parents. Our gift is for you: this card is from us."],"source":"Lettre écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Message d’Emma","participants":[{"nom":"Emma","emoji":"👧","cote":"gauche"},{"nom":"Lou","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Emma","texte":"Thanks! I get up at six on Saturdays. I wash and I dress quickly. I don’t feel tired."}],"source":"Message écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux pronoms réfléchis** de la lettre.","aide":"Ils se terminent par -self.","type":"zone","document":"carte","multiple":true},{"enonce":"Associe chaque pronom sujet à son pronom complément.","aide":"Le pronom complément suit le verbe ou une préposition.","type":"association","gauche":[{"id":"g0","texte":"I"},{"id":"g1","texte":"she"},{"id":"g2","texte":"we"},{"id":"g3","texte":"they"}],"droite":[{"id":"d0","texte":"me"},{"id":"d1","texte":"us"},{"id":"d2","texte":"them"},{"id":"d3","texte":"her"}]},{"enonce":"Complète avec le pronom réfléchi.","aide":"Il insiste sur celui qui l’a fait : un garçon.","type":"trous","segments":["My brother made the cake ",0,"."],"banque":["himself","itself","herself","him"]},{"enonce":"Pourquoi n’y a-t-il pas de *myself* dans « I wash and I dress quickly » ?","aide":"En français, on dit « je me lave » : et en anglais ?","type":"choix","options":[{"id":"a","texte":"Parce qu’Emma est seule quand elle se prépare."},{"id":"b","texte":"Parce que *myself* est réservé à l’écrit formel."},{"id":"c","texte":"Parce que le sujet est au pluriel dans ce message."},{"id":"d","texte":"Ces verbes ne prennent pas de réfléchi en anglais."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11","m21"]},"explication":"**himself** (deux fois) : ici, le pronom réfléchi sert à **insister** (*il l’a fait lui-même*)."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"I – **me**, she – **her**, we – **us**, they – **them**."},{"cle":{"type":"trous","trous":[["himself"]]},"affichage":"himself","explication":"**himself** : le pronom réfléchi de *he* ; il dit « il l’a fait lui-même »."},{"cle":{"type":"choix","ids":["d"]},"explication":"Certains verbes pronominaux français ne le sont pas en anglais : **I wash**, **I get up**, **I feel**, sans pronom réfléchi."}]$ex$::jsonb),
