   $ex${"titre":"À qui est-ce ?","competence":"argumenter","situation":"Le collège range les objets trouvés. La surveillante interroge les élèves pour rendre chaque objet à son propriétaire.","documents":[{"id":"objets","type":"tableau","titre":"Les objets trouvés","colonnes":["Object","Owner"],"lignes":[["Blue bag","Ava"],["Green scarf","Noah"],["Yellow ball","the twins"]],"enteteLignes":false,"source":"Liste écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Mme Lee, Ava et Noah","participants":[{"nom":"Ms Lee","emoji":"👩","cote":"gauche"},{"nom":"Ava","emoji":"👧","cote":"droite"},{"nom":"Noah","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ms Lee","texte":"It’s late, Ava. Is the blue bag yours?"},{"qui":"Ava","texte":"Yes, it’s mine! I looked for it by myself."},{"qui":"Ms Lee","texte":"Good. Noah, the green scarf is yours, I think."},{"qui":"Noah","texte":"Thanks, miss. And the ball? I think it belongs to the twins."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Le foulard est à Noah. Complète avec le pronom possessif.","aide":"Noah est un garçon.","type":"trous","segments":["The scarf is Noah’s. It’s ",0,"."],"banque":["he","himself","him","his"]},{"enonce":"La balle est aux jumeaux. Complète avec le pronom possessif.","aide":"Il remplace « leur balle », sans nom derrière.","type":"trous","segments":["The ball is the twins’. It’s ",0,"."],"banque":["their","themselves","them","theirs"]},{"enonce":"Touche les **deux mots** qui disent qu’Ava a cherché son sac **toute seule**.","aide":"Cherche la préposition et le pronom réfléchi.","type":"zone","document":"sms","multiple":true},{"enonce":"Range chaque pronom : **complément**, **possessif** ou **réfléchi** ?","aide":"Les réfléchis finissent par -self ou -selves ; les possessifs s’emploient sans nom.","type":"categories","categories":[{"id":"c0","texte":"Pronom complément"},{"id":"c1","texte":"Pronom possessif"},{"id":"c2","texte":"Pronom réfléchi"}],"items":[{"id":"i0","texte":"hers"},{"id":"i1","texte":"themselves"},{"id":"i2","texte":"us"},{"id":"i3","texte":"yourself"},{"id":"i4","texte":"ours"},{"id":"i5","texte":"them"}]},{"enonce":"Que représente *it* dans « It’s late, Ava » ?","aide":"Peut-on remplacer *it* par un objet précis ?","type":"choix","options":[{"id":"a","texte":"La surveillante qui range les objets."},{"id":"b","texte":"Un sujet vide : il parle de l’heure."},{"id":"c","texte":"Le foulard vert que Noah a perdu."},{"id":"d","texte":"Le sac bleu que Mme Lee a trouvé."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["his"]]},"affichage":"his","explication":"**his** : le pronom possessif de *he* est **his**."},{"cle":{"type":"trous","trous":[["theirs"]]},"affichage":"theirs","explication":"**theirs** : le pronom possessif de *they* s’emploie sans nom."},{"cle":{"type":"zone","ids":["m15","m16"]},"explication":"**by myself** : *by* + pronom réfléchi veut dire « tout seul »."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c0","i3":"c2","i4":"c1","i5":"c0"}},"explication":"**them, us** : compléments ; **hers, ours** : possessifs ; **themselves, yourself** : réfléchis."},{"cle":{"type":"choix","ids":["b"]},"explication":"**It** est ici un **sujet vide** : il parle de l’heure, comme dans *It’s cold* ou *It’s five o’clock*."}]$ex$::jsonb),
