   $ex$[{"cle":{"type":"zone","ids":["m9"]},"explication":"**who** (sans virgules) : la relative est **déterminative**, elle précise de quel professeur on parle."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"**Déterminative** : sans virgules, indispensable. **Explicative** : entre virgules, information en plus."},{"cle":{"type":"choix","ids":["c"]},"explication":"*that* est **complément** dans une relative déterminative : il peut être **omis** (*the song he played*)."},{"cle":{"type":"trous","trous":[["who"]]},"affichage":"who","explication":"**who** : dans une relative explicative, on ne peut pas employer *that* ; pour une personne, c’est **who**."}]$ex$::jsonb),
