  ('061ffe93-f193-57de-a631-c208fc865ae8'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Il fait froid, non ?","competence":"comprendre-langue","situation":"Tom et Lily se retrouvent devant le collège un matin d’hiver. Ils cherchent l’accord de l’autre.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Tom et Lily","participants":[{"nom":"Tom","emoji":"👦","cote":"gauche"},{"nom":"Lily","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"It’s cold today, isn’t it?"},{"qui":"Lily","texte":"Yes, it is! You’re wearing your new coat, aren’t you?"},{"qui":"Tom","texte":"Yes. It’s warm and I love it."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux auxiliaires négatifs** qui commencent les question tags.","aide":"Ils finissent par n’t.","type":"zone","document":"sms","multiple":true},{"enonce":"Complète le question tag.","aide":"Phrase affirmative, tag négatif.","type":"trous","segments":["She is a teacher, ",0," she?"],"banque":["doesn’t","is","isn’t","aren’t"]},{"enonce":"Pourquoi Tom dit-il « isn’t it » après « It’s cold today » ?","aide":"Regarde si « It’s cold » est affirmatif ou négatif.","type":"choix","options":[{"id":"a","texte":"Parce que *cold* est un adjectif."},{"id":"b","texte":"Parce que la phrase est affirmative : le tag est négatif."},{"id":"c","texte":"Parce que la phrase est négative : le tag est affirmatif."},{"id":"d","texte":"Parce que *it* est toujours suivi de *isn’t*."}],"multiple":false}]}$ex$::jsonb,
