   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**they** : *Somebody called, didn’t they?* — avec somebody, nobody, everyone, on reprend **they**."},{"cle":{"type":"trous","trous":[["aren t"]]},"affichage":"aren’t","explication":"**aren’t** : *I am late, aren’t I?* est la seule forme possible."},{"cle":{"type":"trous","trous":[["aren t"]]},"affichage":"aren’t","explication":"**aren’t** : le tag reprend **there** et l’auxiliaire *are*."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"*Let’s* → **shall we** ; impératif → **will you** ; *nobody* (négatif) → **did they** ; *There aren’t* → **are there** (tag affirmatif)."},{"cle":{"type":"ordre","ids":["e","b","a","c","d"]},"explication":"**Ella has left, hasn’t she?** : le tag reprend *has*, inverse la polarité et répète le pronom."}]$ex$::jsonb),
  ('c93c33d5-5821-52be-8a6f-7306d97cc9a7'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une carte postale d’Édimbourg","competence":"comprendre-langue","situation":"Lena passe le week-end à Édimbourg. Elle écrit une carte postale à sa grand-mère.","documents":[{"id":"carte","type":"fiche","modele":"carte-postale","titre":"Postcard","entete":"Greetings from Edinburgh","emoji":"🏰","lignes":[{"texte":"What a beautiful city!","id":"z1"},{"texte":"How cold it is!","id":"z2"},{"texte":"What lovely people!","id":"z3"},{"texte":"What a pity you aren’t here!","id":"z4"}],"pied":"Love, Lena","teinte":"bleu","source":"Carte écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **deux phrases** qui commencent par *What a* (un nom au singulier).","aide":"Cherche les phrases où *What* est suivi de l’article *a*.","type":"zone","document":"carte","multiple":true},{"enonce":"Pourquoi n’y a-t-il pas de *a* dans « What lovely people! » ?","aide":"On met *a* seulement devant un nom singulier.","type":"choix","options":[{"id":"a","texte":"Parce qu’on ne met jamais *a* après *what*"},{"id":"b","texte":"Parce que *lovely* commence par une consonne"},{"id":"c","texte":"Parce que la phrase est au passé"},{"id":"d","texte":"Parce que *people* est un pluriel"}],"multiple":false},{"enonce":"Complète l’exclamation.","aide":"Le mot est suivi d’un nom (*cakes*).","type":"trous","segments":[0," delicious cakes!"],"banque":["What","Such","So","How"]},{"enonce":"Remets en ordre : « Quelle belle journée ! » La phrase commence par *What*.","aide":"Après *What*, l’article vient avant l’adjectif.","type":"ordre","items":[{"id":"a","texte":"beautiful"},{"id":"b","texte":"What"},{"id":"c","texte":"a"},{"id":"d","texte":"day"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z4"]},"explication":"**What a beautiful city!** et **What a pity…!** : devant un nom singulier dénombrable, on dit *What a* + nom."},{"cle":{"type":"choix","ids":["d"]},"explication":"**people** est un pluriel : après *What*, un nom pluriel s’emploie **sans article**."},{"cle":{"type":"trous","trous":[["what"]]},"affichage":"What","explication":"**What delicious cakes!** : *what* introduit une exclamation devant un nom."},{"cle":{"type":"ordre","ids":["b","c","a","d"]},"explication":"**What a beautiful day!** : What + a + adjectif + nom."}]$ex$::jsonb),
  ('c93c33d5-5821-52be-8a6f-7306d97cc9a7'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le voyage scolaire à Bath","competence":"manier-langue","situation":"Zoe revient d’une sortie scolaire à Bath. Elle raconte tout à son ami Ben par messages.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Zoe et Ben","participants":[{"nom":"Zoe","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Zoe","texte":"The trip to Bath was great! What a lovely town!"},{"qui":"Ben","texte":"How lucky you are! Which part did you like best?"},{"qui":"Zoe","texte":"The Roman baths! They are such old buildings!"},{"qui":"Ben","texte":"No way! I’m so jealous!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui introduisent une exclamation dans les messages.","aide":"L’un est suivi d’un nom, l’autre d’un adjectif.","type":"zone","document":"sms","multiple":true},{"enonce":"Range chaque exclamation selon le mot qui la commence.","aide":"*What* est suivi d’un nom, *how* d’un adjectif ou d’un adverbe.","type":"categories","categories":[{"id":"c0","texte":"What"},{"id":"c1","texte":"How"}],"items":[{"id":"i0","texte":"___ a great idea!"},{"id":"i1","texte":"___ tall your brother is!"},{"id":"i2","texte":"___ funny he is!"},{"id":"i3","texte":"___ delicious cakes!"},{"id":"i4","texte":"___ quickly she runs!"},{"id":"i5","texte":"___ an amazing view!"}]},{"enonce":"Complète la phrase.","aide":"Un adjectif seul suit ce mot.","type":"trous","segments":["She is ",0," kind!"],"banque":["what","such a","so","such"]},{"enonce":"Comment dit-on « Comme elle court vite ! » ?","aide":"Après *how*, l’adjectif ou l’adverbe vient tout de suite, puis le sujet et le verbe.","type":"choix","options":[{"id":"a","texte":"How fast does she run!"},{"id":"b","texte":"How she runs fast!"},{"id":"c","texte":"How fast she runs!"},{"id":"d","texte":"What fast she runs!"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m10"]},"explication":"**What** (devant le nom *town*) et **How** (devant l’adjectif *lucky*) : ce sont les deux mots de l’exclamation."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"**What** + nom (*idea*, *cakes*, *view*) ; **how** + adjectif ou adverbe (*funny*, *quickly*, *tall*)."},{"cle":{"type":"trous","trous":[["so"]]},"affichage":"so","explication":"**so kind** : *so* est suivi d’un adjectif seul ; *such* demande un nom."},{"cle":{"type":"choix","ids":["c"]},"explication":"**How fast she runs!** : how + adverbe + sujet + verbe, **sans inversion**."}]$ex$::jsonb),
  ('c93c33d5-5821-52be-8a6f-7306d97cc9a7'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le camp d’été du lac","competence":"manier-langue","situation":"Mia passe une semaine dans un camp d’été au bord du lac Windermere. Elle lit l’affiche du camp, puis écrit à sa grand-mère.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","titre":"Camp poster","entete":"Lakeside Summer Camp","sousTitre":"Windermere — July","emoji":"⛺","lignes":[{"texte":"What a place for a holiday!","id":"z1"},{"texte":"What great activities!","id":"z2"},{"texte":"Climbing, canoeing and campfires","id":"z3"},{"texte":"How exciting your week will be!","id":"z4"}],"teinte":"vert","source":"Affiche écrite pour l’exercice"},{"id":"mail","type":"texte","genre":"lettre","titre":"Mia’s email","blocs":["Dear Gran,","The camp is so big and the food is so good! We sleep in such a lovely cabin, with six bunk beds. Yesterday it rained: what a pity, no canoeing! But Mr Lee makes such delicious pancakes. How happy I am here!","Love, Mia"],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche la ligne où *What* est suivi d’un **nom pluriel**, sans article.","aide":"Cherche la ligne qui n’a pas *a* après *What*.","type":"zone","document":"affiche","multiple":false},{"enonce":"Touche les **deux mots *so*** : ils sont suivis d’un adjectif seul.","aide":"Il y en a un devant *big* et un devant *good*.","type":"zone","document":"mail","multiple":true},{"enonce":"Associe chaque construction à ce qui la suit.","aide":"Regarde si le nom est singulier ou pluriel, et s’il y a un nom ou non.","type":"association","gauche":[{"id":"g0","texte":"so"},{"id":"g1","texte":"such a"},{"id":"g2","texte":"such"},{"id":"g3","texte":"What a"}],"droite":[{"id":"d0","texte":"un nom singulier dans une exclamation (What a pity!)"},{"id":"d1","texte":"un adjectif + un nom pluriel (such delicious pancakes)"},{"id":"d2","texte":"un adjectif + un nom singulier (such a lovely cabin)"},{"id":"d3","texte":"un adjectif ou un adverbe seul (so big)"}]},{"enonce":"Mia hésite devant « How beautiful is this lake! ». Que faut-il corriger ?","aide":"L’anglais ne fait pas d’inversion dans l’exclamation.","type":"choix","options":[{"id":"a","texte":"Ajouter *a* après *How* : *How a beautiful is this lake!*"},{"id":"b","texte":"Ne rien corriger : la phrase est déjà correcte comme ça"},{"id":"c","texte":"Remplacer *How* par *What* : *What beautiful is this lake!*"},{"id":"d","texte":"Remettre le sujet avant le verbe : *How beautiful this lake is!*"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Le nom *day* est au singulier, avec *a*.","type":"trous","segments":["It was ",0," a lovely day!"],"banque":["such","how","so","what"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**What great activities!** : *activities* est un pluriel, donc pas d’article."},{"cle":{"type":"zone","ids":["m5","m11"]},"explication":"**so big** et **so good** : *so* + adjectif. Pour un nom, on emploie *such* (*such a lovely cabin*)."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"**so** + adjectif ; **such a** + adjectif + nom singulier ; **such** + adjectif + nom pluriel ; **What a** + nom singulier."},{"cle":{"type":"choix","ids":["d"]},"explication":"**How beautiful this lake is!** : dans une exclamation, le sujet reste **avant** le verbe."},{"cle":{"type":"trous","trous":[["such"]]},"affichage":"such","explication":"**such a lovely day** : *such a* + adjectif + nom singulier."}]$ex$::jsonb),
  ('49a7648e-c39b-5aa0-92a2-1c524fb71aae'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Bienvenue à Harbour School","competence":"comprendre-langue","situation":"Sam visite le site de son nouveau collège anglais. Il lit la page de présentation.","documents":[{"id":"page","type":"texte","genre":"article","titre":"Harbour School","blocs":["Harbour School was built in 1960. The classrooms are cleaned every evening. Lunch is served at noon in the big hall. The school bus is always full!"],"source":"Page écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **trois participes passés** qui montrent que les phrases sont au passif.","aide":"Ils suivent *was* ou *are* / *is*.","type":"zone","document":"page","multiple":true},{"enonce":"Remets en ordre : « Le déjeuner est servi à midi. » La phrase commence par *Lunch*.","aide":"Sujet, *be*, participe passé, puis l’heure.","type":"ordre","items":[{"id":"a","texte":"served"},{"id":"b","texte":"is"},{"id":"c","texte":"Lunch"},{"id":"d","texte":"at"},{"id":"e","texte":"noon"}]},{"enonce":"Quelle est la phrase passive qui correspond à « They clean the classrooms every evening » ?","aide":"Le complément (*the classrooms*) devient sujet, puis *be* + participe passé.","type":"choix","options":[{"id":"a","texte":"The classrooms clean every evening."},{"id":"b","texte":"The classrooms cleaned every evening."},{"id":"c","texte":"The classrooms are cleaned every evening."},{"id":"d","texte":"The classrooms are cleaning every evening."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m9","m14"]},"explication":"**built**, **cleaned**, **served** : le passif se forme avec *be* + participe passé."},{"cle":{"type":"ordre","ids":["c","b","a","d","e"]},"explication":"**Lunch is served at noon.** : sujet + *is* + participe passé."},{"cle":{"type":"choix","ids":["c"]},"explication":"**The classrooms are cleaned every evening.** : présent simple actif → *are* + participe passé."}]$ex$::jsonb),
  ('49a7648e-c39b-5aa0-92a2-1c524fb71aae'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les boutiques d’une petite ville","competence":"manier-langue","situation":"Le journal d’une petite ville écrit sur ses commerces. Il passe de l’actif au passif selon les époques.","documents":[{"id":"tab","type":"tableau","titre":"Active and passive","colonnes":["Temps","Phrase active","Phrase passive"],"lignes":[["Présent","They open the shop at nine.","The shop is opened at nine."],["Prétérit","They opened the shop in 2010.","?"],["Present perfect","They have opened a new shop.","?"],["Futur","They will open another shop.","?"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case où la phrase est **déjà** au passif, au présent.","aide":"Regarde la dernière colonne, première ligne.","type":"zone","document":"tab","multiple":false},{"enonce":"Complète la phrase passive du prétérit : « The shop ___ ___ in 2010. »","aide":"Le prétérit de *be* au singulier, puis le participe passé.","type":"trous","segments":["The shop ",0," ",1," in 2010."],"banque":["is","open","opened","was"]},{"enonce":"Quelle est la phrase passive du present perfect : « They have opened a new shop » ?","aide":"Present perfect de *be* : *has been* ; puis le participe passé.","type":"choix","options":[{"id":"a","texte":"A new shop has been opened."},{"id":"b","texte":"A new shop was been opened."},{"id":"c","texte":"A new shop has opened be."},{"id":"d","texte":"A new shop is been opened."}],"multiple":false},{"enonce":"Remets en ordre la phrase passive du futur. Elle commence par *Another*.","aide":"Au futur, on a *will be* + participe passé.","type":"ordre","items":[{"id":"a","texte":"opened"},{"id":"b","texte":"shop"},{"id":"c","texte":"Another"},{"id":"d","texte":"be"},{"id":"e","texte":"will"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"**The shop is opened at nine.** : *is* + participe passé, au présent."},{"cle":{"type":"trous","trous":[["was"],["opened"]]},"affichage":"was · opened","explication":"**The shop was opened in 2010.** : prétérit de *be* + participe passé."},{"cle":{"type":"choix","ids":["a"]},"explication":"**A new shop has been opened.** : *has been* + participe passé."},{"cle":{"type":"ordre","ids":["c","b","e","d","a"]},"explication":"**Another shop will be opened.** : *will* + *be* + participe passé."}]$ex$::jsonb),
  ('49a7648e-c39b-5aa0-92a2-1c524fb71aae'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le vélo volé","competence":"analyser-document","situation":"Lina s’est fait voler son vélo à la gare. Elle prévient son père par message, puis lit un article du journal local.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Lina et de son père","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Dad","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"Dad, my bike was stolen this morning!"},{"qui":"Dad","texte":"Oh no! Where was it left?"},{"qui":"Lina","texte":"At the station. It was locked, but it’s gone."},{"qui":"Dad","texte":"The police will be told. Maybe it will be found."},{"qui":"Lina","texte":"I hope so. It was given to me by Grandpa!"}],"source":"Messages écrits pour l’exercice"},{"id":"journal","type":"texte","genre":"article","titre":"Newtown News","blocs":["The old bridge was built in 1890. It has been repaired twice. Next spring, a new library will be opened by the mayor, and the bridge will be closed for a week. Meetings are held in the town hall every Monday."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche le **participe passé** qui montre que Lina ne sait pas qui a pris son vélo.","aide":"C’est le verbe qui dit ce qui est arrivé au vélo ce matin.","type":"zone","document":"sms","multiple":false},{"enonce":"Dans l’article, associe chaque verbe passif à son temps.","aide":"Regarde la forme de *be* : *was*, *has been*, *will be*, *are*.","type":"association","gauche":[{"id":"g0","texte":"was built"},{"id":"g1","texte":"has been repaired"},{"id":"g2","texte":"will be opened"},{"id":"g3","texte":"are held"}],"droite":[{"id":"d0","texte":"present perfect"},{"id":"d1","texte":"présent"},{"id":"d2","texte":"futur"},{"id":"d3","texte":"prétérit"}]},{"enonce":"Touche le mot qui introduit **l’auteur** de l’action dans l’article.","aide":"L’auteur est le maire (*the mayor*).","type":"zone","document":"journal","multiple":false},{"enonce":"« They gave Lina a bike. » Quelle phrase passive est la plus courante ?","aide":"Avec *give*, la personne devient souvent le sujet du passif.","type":"choix","options":[{"id":"a","texte":"Lina was given to a bike."},{"id":"b","texte":"A bike was given Lina."},{"id":"c","texte":"Lina was given a bike."},{"id":"d","texte":"Lina has been given by a bike."}],"multiple":false},{"enonce":"Remets en ordre : « Mon téléphone a été retrouvé. » La phrase commence par *My*.","aide":"Present perfect passif : *has been* + participe passé.","type":"ordre","items":[{"id":"a","texte":"My"},{"id":"b","texte":"phone"},{"id":"c","texte":"been"},{"id":"d","texte":"found"},{"id":"e","texte":"has"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**stolen** : on emploie le passif quand l’auteur de l’action est **inconnu**."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g2":"d2","g0":"d3"}},"explication":"*was built* : prétérit ; *has been repaired* : present perfect ; *will be opened* : futur ; *are held* : présent."},{"cle":{"type":"zone","ids":["m20"]},"explication":"**by** introduit le complément d’agent. Il n’apparaît que quand l’auteur est important."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Lina was given a bike.** : avec deux compléments, le plus courant fait de la personne le sujet."},{"cle":{"type":"ordre","ids":["a","b","e","c","d"]},"explication":"**My phone has been found.** : *has been* + participe passé."}]$ex$::jsonb),
