  ('20deed1b-d518-5549-9c9f-3c0098217864'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une nouvelle vie à Toronto","competence":"argumenter","situation":"Hugo a déménagé de France à Toronto. Il raconte à son ami Ben ce qui a changé dans sa vie.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Hugo’s letter","blocs":["Dear Ben,","I moved to Toronto in September. In France I used to cycle to school, and every winter we would go skiing in the Alps. I used to be very shy, but now I have new friends.","At first, I wasn’t used to the cold. Now I’m getting used to it, and I’m used to taking the bus every morning.","See you soon! Hugo"],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui montre que Hugo s’habitue **peu à peu** au froid.","aide":"L’idée de progression se trouve dans un verbe en *-ing*.","type":"zone","document":"lettre","multiple":false},{"enonce":"Dans quelle phrase ne peut-on **pas** remplacer *used to* par *would* ?","aide":"*Would* ne s’emploie que pour des actions répétées, pas pour un état.","type":"choix","options":[{"id":"a","texte":"I used to cycle to school."},{"id":"b","texte":"I used to be very shy."},{"id":"c","texte":"I used to take the train to Paris every Friday."},{"id":"d","texte":"I used to visit my cousins every summer."}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Après *get used to*, on emploie un verbe en *-ing*.","type":"trous","segments":["At school, he is getting used to ",0," in English."],"banque":["speaking","speak","to speak","spoke"]},{"enonce":"Remets en ordre : « Je n’aimais pas le froid. » La phrase commence par *I*.","aide":"Après *didn’t*, on dit *use* (sans -d).","type":"ordre","items":[{"id":"a","texte":"cold"},{"id":"b","texte":"didn’t"},{"id":"c","texte":"I"},{"id":"d","texte":"the"},{"id":"e","texte":"like"},{"id":"f","texte":"to"},{"id":"g","texte":"use"}]},{"enonce":"Associe chaque structure à son sens.","aide":"Pense à ce qui suit chaque structure.","type":"association","gauche":[{"id":"g0","texte":"used to + base verbale"},{"id":"g1","texte":"be used to + -ING"},{"id":"g2","texte":"get used to + -ING"},{"id":"g3","texte":"would + base verbale"}],"droite":[{"id":"d0","texte":"une action répétée dans le passé (jamais un état)"},{"id":"d1","texte":"s’habituer peu à peu"},{"id":"d2","texte":"être habitué à"},{"id":"d3","texte":"une habitude passée révolue"}]}]}$ex$::jsonb,
