   $ex${"titre":"Les messages de maman","competence":"analyser-document","situation":"Zoé échange avec sa mère avant une soirée. Le lendemain, elle raconte la conversation à son amie.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de maman et de Zoé","participants":[{"nom":"Mum","emoji":"👩","cote":"gauche"},{"nom":"Zoe","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Mum","texte":"Don’t be late tonight."},{"qui":"Zoe","texte":"I will be home at six."},{"qui":"Mum","texte":"Did you finish your homework?"},{"qui":"Zoe","texte":"I haven’t finished it yet. I will do it tomorrow."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Comment rapporte-t-on l’ordre « Don’t be late tonight » ?","aide":"Un ordre rapporté : *tell* + personne + *to* + base verbale.","type":"choix","options":[{"id":"a","texte":"Mum said Zoe not be late that night."},{"id":"b","texte":"Mum told Zoe didn’t be late that night."},{"id":"c","texte":"Mum told Zoe that she doesn’t be late that night."},{"id":"d","texte":"Mum told Zoe not to be late that night."}],"multiple":false},{"enonce":"Mum a posé une question fermée. Complète.","aide":"Une question qui appelle « oui » ou « non » se rapporte avec un mot de doute.","type":"trous","segments":["Mum asked Zoe ",0," she had finished her homework."],"banque":["whether","that","if","what"]},{"enonce":"Touche les **deux repères de temps** qui changent au discours indirect.","aide":"*Tonight* et *tomorrow* ne se disent plus tels quels.","type":"zone","document":"sms","multiple":true},{"enonce":"Associe chaque élément du discours direct à sa forme rapportée.","aide":"Applique le recul des temps et les changements de repères.","type":"association","gauche":[{"id":"g0","texte":"tonight"},{"id":"g1","texte":"tomorrow"},{"id":"g2","texte":"I will be home"},{"id":"g3","texte":"I haven’t finished"}],"droite":[{"id":"d0","texte":"the next day"},{"id":"d1","texte":"she hadn’t finished"},{"id":"d2","texte":"she would be home"},{"id":"d3","texte":"that night"}]},{"enonce":"Remets en ordre : « Maman a demandé si elle était prête. » La phrase commence par *Mum*.","aide":"Après *if*, on garde l’ordre sujet + verbe.","type":"ordre","items":[{"id":"a","texte":"ready"},{"id":"b","texte":"Mum"},{"id":"c","texte":"she"},{"id":"d","texte":"asked"},{"id":"e","texte":"if"},{"id":"f","texte":"was"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"**told Zoe not to be late** : ordre négatif = *tell* + complément + *not to* + base verbale."},{"cle":{"type":"trous","trous":[["if","whether"]]},"affichage":"if","explication":"**if** ou **whether** : introduit une question fermée rapportée, sans inversion."},{"cle":{"type":"zone","ids":["m3","m24"]},"explication":"**tonight** → *that night* ; **tomorrow** → *the next day*."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g2":"d2","g0":"d3"}},"explication":"*tonight* → **that night** ; *tomorrow* → **the next day** ; *will* → **would** ; *haven’t finished* → **hadn’t finished**."},{"cle":{"type":"ordre","ids":["b","d","e","c","f","a"]},"explication":"**Mum asked if she was ready.** : question rapportée avec *if*, ordre de l’affirmative."}]$ex$::jsonb),
