   $ex${"titre":"Le même cheval de bronze, trois endroits","competence":"analyser-document","situation":"Une statue de cheval en bronze a changé trois fois d’endroit. Un professeur demande à ses élèves si le sens de l’œuvre change aussi, et ce que les titres de quatre peintures leur disent.","documents":[{"id":"lieux","type":"tableau","titre":"Les trois endroits du cheval","colonnes":["Où il est posé","Qui passe devant"],"lignes":[["Vitrine d’une boutique","Des clients qui hésitent à acheter"],["Salle d’un musée","Des visiteurs qui lisent le cartel"],["Place du village","Tous les habitants, chaque jour"]],"source":"Situation imaginée pour l’exercice"},{"id":"titres","type":"tableau","titre":"Quatre peintures de l’exposition","colonnes":["Peinture","Titre"],"lignes":[["Peinture 1","Sans titre"],["Peinture 2","Le dernier train de 17 h 42"],["Peinture 3","Sans titre"],["Peinture 4","Retour de pêche"]],"source":"Titres imaginés pour l’exercice"}],"questions":[{"enonce":"Associe chaque endroit à ce que devient la statue.","aide":"Pense à qui regarde la statue, et pourquoi.","type":"association","gauche":[{"id":"g0","texte":"Vitrine d’une boutique"},{"id":"g1","texte":"Salle d’un musée"},{"id":"g2","texte":"Place du village"}],"droite":[{"id":"d0","texte":"Un patrimoine"},{"id":"d1","texte":"Une marchandise"},{"id":"d2","texte":"Une affaire de tous"}]},{"enonce":"Range chaque peinture selon ce que fait son titre.","aide":"*Sans titre* est un choix : l’artiste ne veut pas fermer le sens.","type":"categories","categories":[{"id":"c0","texte":"Le titre oriente le sens"},{"id":"c1","texte":"Le titre laisse le sens libre"}],"items":[{"id":"i0","texte":"Peinture 1"},{"id":"i1","texte":"Peinture 4"},{"id":"i2","texte":"Peinture 3"},{"id":"i3","texte":"Peinture 2"}]},{"enonce":"Le cheval quitte le musée pour une vitrine de boutique. Que devient son sens ?","aide":"Une même forme n’a pas le même effet selon l’endroit.","type":"choix","options":[{"id":"a","texte":"Il devient plus fort, car le bronze brille davantage"},{"id":"b","texte":"Il change, car le lieu change ce que l’œuvre dit"},{"id":"c","texte":"Il disparaît, car une vitrine n’expose pas d’art"},{"id":"d","texte":"Il ne change pas, car la forme reste la même"}],"multiple":false}]}$ex$::jsonb,
