   $ex${"titre":"Des fils rouges dans le hall de la gare","competence":"analyser-document","situation":"Une installation vient d’être montée dans le hall d’une gare. Trois visiteurs ont donné leur avis. Zoé relit le cartel et leurs réactions pour comprendre comment le lieu, le spectateur et le titre font l’œuvre.","documents":[{"id":"cartel","type":"fiche","modele":"affiche","titre":"Le cartel de l’œuvre","entete":"Hall de la gare","sousTitre":"Installation","emoji":"🧶","lignes":[{"texte":"400 fils de laine rouge tendus d’un mur à l’autre","id":"z1"},{"texte":"Le public doit se faufiler entre les fils pour traverser","id":"z2"},{"texte":"Œuvre conçue pour ce hall, et pas pour un autre lieu","id":"z3"},{"texte":"Titre : *Sans titre*","id":"z4"}],"pied":"Cartel imaginé pour l’exercice"},{"id":"avis","type":"texte","genre":"source","titre":"Les avis des visiteurs","auteur":"Avis imaginés pour l’exercice","blocs":["Un visiteur : « Je me sens pris dans une toile d’araignée. »","Une voyageuse : « Cela me fait penser aux gens pressés qui se croisent sans se voir. »","Un élève : « Je ne sais pas ce que cela veut dire, et c’est très bien comme ça. »"]}],"questions":[{"enonce":"Touche la ligne qui prouve que cette œuvre est **une installation**.","aide":"Une installation se caractérise par le fait que le spectateur y entre ou la parcourt.","type":"zone","document":"cartel","multiple":false},{"enonce":"Touche la ligne qui montre que l’œuvre est **in situ**.","aide":"Cherche l’information qui lie l’œuvre à son lieu.","type":"zone","document":"cartel","multiple":false},{"enonce":"Les trois visiteurs voient trois choses différentes. Quel élément du cartel l’explique ?","aide":"Un titre précis ferme le sens ; l’autre choix le laisse ouvert.","type":"choix","options":[{"id":"a","texte":"La couleur rouge, qui impose un sens unique"},{"id":"b","texte":"Le nom du hall, qui oriente tout le monde"},{"id":"c","texte":"Le nombre de fils, qui change la lecture"},{"id":"d","texte":"Le titre *Sans titre*, qui laisse le sens libre"}],"multiple":false},{"enonce":"Complète la leçon que Zoé retient.","aide":"Relis ce qui a été dit du hall de la gare et de *Sans titre*.","type":"trous","segments":["Changer une œuvre de ",0," change son ",1," ; son ",2," fait partie de l’œuvre."],"banque":["lieu","sens","prix","titre","cadre"]}]}$ex$::jsonb,
