   $ex${"titre":"Plein, vide et socle","competence":"observer-schema","situation":"Sana compare deux sculptures : l’une est posée sur un socle, l’autre est percée et se tient au sol, au niveau du visiteur. Elle veut comprendre ce que le vide et le socle font à l’œuvre.","documents":[{"id":"sculptures","type":"schema","titre":"Deux sculptures côte à côte","largeur":320,"hauteur":240,"elements":[{"forme":"ligne","de":[20,195],"a":[300,195],"teinte":"encre"},{"forme":"rect","x":30,"y":150,"l":90,"h":45,"teinte":"gris","motif":"plein","id":"z1","zone":true},{"forme":"ellipse","cx":75,"cy":100,"rx":28,"ry":50,"teinte":"brun","motif":"plein","id":"z2","zone":true},{"forme":"ellipse","cx":215,"cy":145,"rx":32,"ry":50,"teinte":"brun","motif":"plein","id":"z3","zone":true},{"forme":"cercle","cx":215,"cy":140,"r":13,"teinte":"blanc","motif":"plein","id":"z4","zone":true},{"forme":"emoji","x":280,"y":175,"emoji":"🧍","taille":30},{"forme":"texte","x":75,"y":220,"texte":"Avec socle","ancre":"milieu","gras":true},{"forme":"texte","x":215,"y":220,"texte":"Sans socle","ancre":"milieu","gras":true}],"source":"Schéma dessiné pour l’exercice"}],"questions":[{"enonce":"Touche **le vide** qui fait partie de la sculpture percée.","aide":"Cherche l’endroit où l’on voit à travers la figure.","type":"zone","document":"sculptures","multiple":false},{"enonce":"Touche **ce qui isole** la première sculpture du sol du visiteur.","aide":"C’est le bloc sur lequel la figure est posée.","type":"zone","document":"sculptures","multiple":false},{"enonce":"Complète ce que Sana retient.","aide":"Pense à la figure à droite : elle est au même niveau que le visiteur.","type":"trous","segments":["Avec un socle, l’œuvre est ",0," du monde réel ; sans socle, elle descend dans ",1," espace."],"banque":["son","notre","isolée","rapprochée"]},{"enonce":"Quel sculpteur perce ses figures pour que l’espace les traverse ?","aide":"Il fait du vide une partie de l’œuvre.","type":"choix","options":[{"id":"a","texte":"Max Ernst"},{"id":"b","texte":"Jackson Pollock"},{"id":"c","texte":"Henry Moore"},{"id":"d","texte":"Marcel Duchamp"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"Le **trou** est un vide qui fait partie de l’œuvre : l’espace traverse la sculpture, comme chez Henry Moore."},{"cle":{"type":"zone","ids":["z1"]},"explication":"Le **socle** isole l’œuvre et la désigne comme art, à distance de notre espace."},{"cle":{"type":"trous","trous":[["isolee"],["notre"]]},"affichage":"isolée · notre","explication":"Avec socle, l’œuvre est **isolée** et désignée comme art ; sans socle, elle descend dans **notre** espace, au même niveau que nous."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Henry Moore** perce ses figures : l’espace les traverse et devient partie de l’œuvre."}]$ex$::jsonb),
