   $ex${"titre":"Fontaine, un urinoir au musée ?","competence":"analyser-document","situation":"Une exposition sur l’histoire de l’art du XXe siècle présente *Fontaine*. Chaïma lit le cartel et la frise de l’époque pour comprendre pourquoi cet objet a tant fait parler.","documents":[{"id":"cartel","type":"fiche","modele":"affiche","titre":"Le cartel de Fontaine","entete":"Fontaine","sousTitre":"Marcel Duchamp, 1917","emoji":"🚽","lignes":[{"texte":"Objet : un urinoir renversé et signé","id":"z1"},{"texte":"Fabriqué par l’artiste : non","id":"z2"},{"texte":"Statut : ready-made","id":"z3"}],"pied":"Cartel écrit pour l’exercice"},{"id":"frise","type":"frise","titre":"Le début du XXe siècle","debut":1900,"fin":1950,"pas":10,"periodes":[{"id":"z4","debut":1914,"fin":1918,"nom":"Première Guerre mondiale","teinte":"corail"}],"evenements":[{"id":"z5","date":1917,"nom":"Fontaine"}]}],"questions":[{"enonce":"Touche la ligne qui montre que l’artiste **n’a pas fabriqué** l’objet.","aide":"Cherche l’information qui parle de la fabrication.","type":"zone","document":"cartel","multiple":false},{"enonce":"Touche la **période de l’histoire** pendant laquelle Duchamp présente *Fontaine*.","aide":"*Fontaine* date de 1917 : cherche la période qui contient cette année.","type":"zone","document":"frise","multiple":false},{"enonce":"Range chaque œuvre selon que l’artiste l’a fabriquée ou seulement choisie.","aide":"Dans un ready-made, l’artiste ne fabrique pas l’objet.","type":"categories","categories":[{"id":"c0","texte":"Fabriquée par l’artiste"},{"id":"c1","texte":"Objet choisi par l’artiste"}],"items":[{"id":"i0","texte":"Un portrait modelé en argile"},{"id":"i1","texte":"Un urinoir acheté, renversé et signé"},{"id":"i2","texte":"Une roue de bicyclette posée sur un tabouret"},{"id":"i3","texte":"Une figure coulée en bronze"},{"id":"i4","texte":"Une statue taillée dans la pierre"}]},{"enonce":"Selon Duchamp, qu’est-ce qui fait l’œuvre dans un ready-made ?","aide":"Ce n’est pas le travail de la main qui compte ici.","type":"choix","options":[{"id":"a","texte":"La qualité de fabrication de l’objet"},{"id":"b","texte":"La beauté de l’objet"},{"id":"c","texte":"Le choix de l’objet et son déplacement"},{"id":"d","texte":"Le prix payé par l’artiste"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Duchamp n’a pas fabriqué l’objet : il l’a **choisi** et déplacé. C’est le principe du **ready-made**."},{"cle":{"type":"zone","ids":["z4"]},"explication":"1917 est comprise entre 1914 et 1918 : *Fontaine* date de la **Première Guerre mondiale**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c0"}},"explication":"Tailler, modeler et couler sont des **fabrications**. Un urinoir ou une roue de bicyclette sont des **objets choisis** : ce sont des ready-mades."},{"cle":{"type":"choix","ids":["c"]},"explication":"Ce qui fait l’œuvre, ce n’est pas la fabrication mais le **choix** de l’objet et son **déplacement** dans un autre contexte."}]$ex$::jsonb),
