   $ex${"titre":"La loi de 1905","competence":"analyser-texte","situation":"La loi du 9 décembre 1905 est le texte fondateur de la laïcité. Voici ses deux idées, présentées dans un extrait adapté.","documents":[{"id":"loi","type":"texte","genre":"source","titre":"La loi de séparation (adaptée)","blocs":["La République garantit la liberté de conscience et le libre exercice des cultes.","Elle ne reconnaît, ne salarie et ne subventionne aucun culte."],"source":"D’après la loi du 9 décembre 1905 (texte adapté pour l’exercice)."}],"questions":[{"enonce":"Touche les trois verbes qui expriment le principe de séparation de l’État et des cultes.","aide":"Ils sont dans la deuxième phrase.","type":"zone","document":"loi","multiple":true},{"enonce":"Associe chaque pilier de la laïcité à ce qu’il garantit.","aide":"Chaque pilier a un mot-clé dans son nom.","type":"association","gauche":[{"id":"g0","texte":"Liberté de conscience"},{"id":"g1","texte":"Séparation"},{"id":"g2","texte":"Égalité"}],"droite":[{"id":"d0","texte":"Croire, ne pas croire, changer, pratiquer ou non"},{"id":"d1","texte":"Tous égaux devant la loi, quelle que soit leur croyance"},{"id":"d2","texte":"L’État ne reconnaît ni ne finance aucun culte"}]},{"enonce":"La laïcité, est-ce l’athéisme de l’État ?","aide":"Le texte garantit aussi le libre exercice des cultes.","type":"choix","options":[{"id":"a","texte":"Oui, depuis 1905"},{"id":"b","texte":"Oui : l’État est athée"},{"id":"c","texte":"Non : l’État n’a pas d’opinion sur Dieu"},{"id":"d","texte":"Oui, mais seulement à l’école"}],"multiple":false}]}$ex$::jsonb,
