  ('7c993549-b67d-5ba8-82f0-3f4115a530e7'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Où s’applique la loi de 2004 ?","competence":"lire-tableau","situation":"La loi du 15 mars 2004 interdit les signes religieux ostensibles aux élèves, mais pas partout. Un tableau précise les lieux concernés.","documents":[{"id":"lieux","type":"tableau","titre":"La loi de 2004, lieu par lieu","colonnes":["Le lieu","La loi s’applique-t-elle ?"],"lignes":[["École, collège, lycée publics","Oui"],["Université","Non"],["La rue","Non"],["Établissement privé sous contrat","Non"]],"enteteLignes":true,"source":"Tableau de synthèse écrit pour l’exercice."}],"questions":[{"enonce":"Touche la case qui indique le seul lieu où la loi s’applique.","aide":"Cherche le « Oui ».","type":"zone","document":"lieux","multiple":false},{"enonce":"Sur les quatre lieux du tableau, dans combien la loi de 2004 ne s’applique-t-elle PAS ?","aide":"Compte les « Non ».","type":"nombre","unite":"lieux"},{"enonce":"Un enseignant d’un collège public peut-il manifester ses convictions religieuses en classe ?","aide":"La neutralité s’applique dans l’exercice des fonctions.","type":"choix","options":[{"id":"a","texte":"Non : les agents publics sont neutres dans l’exercice de leurs fonctions"},{"id":"b","texte":"Oui, mais seulement le matin"},{"id":"c","texte":"Non, même dans sa vie privée"},{"id":"d","texte":"Oui : c’est sa liberté d’expression"}],"multiple":false},{"enonce":"Quel régime particulier est toujours en vigueur en Alsace-Moselle ?","aide":"Ces régions étaient allemandes en 1905.","type":"texte","placeholder":"Un nom"}]}$ex$::jsonb,
