  ('d19fcce7-8bb9-532d-a255-c6f7c64a5898'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Mélissa et l’application","competence":"analyser-document","situation":"Mélissa a 14 ans et veut s’inscrire sur une application. Son frère Hugo lui explique ce que dit la loi. La conversation est écrite pour l’exercice.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Conversation de Mélissa et de Hugo","participants":[{"nom":"Mélissa","emoji":"👧","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mélissa","texte":"L’appli demande mon accord pour utiliser mes données. J’ai 14 ans, je peux le donner seule ?"},{"qui":"Hugo","texte":"Non, avant l’âge du consentement autonome, il faut l’accord d’un parent."},{"qui":"Mélissa","texte":"Et si je veux ensuite voir ou effacer mes données ?"},{"qui":"Hugo","texte":"Le RGPD te donne des droits, et tu peux saisir la CNIL."}],"source":"Dialogue écrit pour l’exercice."},{"id":"droits","type":"tableau","titre":"Les droits du RGPD","colonnes":["Le droit","Ce qu’il permet"],"lignes":[["Accès","Savoir quelles données sont détenues"],["Rectification","?"],["Effacement","?"],["Opposition","?"]],"enteteLignes":true,"source":"Tableau de synthèse écrit pour l’exercice."}],"questions":[{"enonce":"À partir de quel âge peut-on consentir seul au traitement de ses données en France ?","aide":"Mélissa n’a pas encore cet âge.","type":"nombre","unite":"ans"},{"enonce":"Que doit faire Mélissa, qui a 14 ans, pour s’inscrire ?","aide":"Elle a moins de 15 ans.","type":"choix","options":[{"id":"a","texte":"Rien : l’appli est gratuite"},{"id":"b","texte":"Mentir sur son âge"},{"id":"c","texte":"Attendre 18 ans"},{"id":"d","texte":"Obtenir l’accord d’un parent"}],"multiple":false},{"enonce":"Associe chaque droit du RGPD à ce qu’il permet.","aide":"Le RGPD est entré en application en 2018.","type":"association","gauche":[{"id":"g0","texte":"Accès"},{"id":"g1","texte":"Rectification"},{"id":"g2","texte":"Effacement"},{"id":"g3","texte":"Opposition"}],"droite":[{"id":"d0","texte":"Refuser un usage de ses données"},{"id":"d1","texte":"Demander leur suppression"},{"id":"d2","texte":"Consulter ses données"},{"id":"d3","texte":"Les corriger"}]},{"enonce":"Quelle autorité française veille à la protection des données personnelles ?","aide":"Elle est citée dans la dernière réplique de Hugo.","type":"texte","placeholder":"Un sigle"}]}$ex$::jsonb,
