 comptes"},{"id":"i4","texte":"Diffuser une image intime"}]},{"enonce":"Pourquoi une publication de collège peut-elle ressortir dix ans plus tard ?","aide":"Pense au chemin schématisé.","type":"choix","options":[{"id":"a","texte":"Parce que seul l’auteur peut la retrouver"},{"id":"b","texte":"Parce que la loi interdit de supprimer"},{"id":"c","texte":"Parce qu’internet efface tout au bout de dix ans"},{"id":"d","texte":"Parce que le contenu a pu être copié et archivé"}],"multiple":false}]}$ex$::jsonb,
