items":[{"id":"i0","texte":"Affirmer à tort qu’un camarade a volé"},{"id":"i1","texte":"Se moquer d’un parti politique par une caricature"},{"id":"i2","texte":"Critiquer une religion ou une idée"},{"id":"i3","texte":"Appeler à s’en prendre à des personnes à cause de leur religion"},{"id":"i4","texte":"Critiquer une loi"},{"id":"i5","texte":"Insulter un camarade dans un commentaire"}]}]}$ex$::jsonb,
