autres sources"},{"id":"c","texte":"En ne vérifiant plus rien"},{"id":"d","texte":"En se désabonnant de toute information"}],"multiple":false},{"enonce":"Combien de sources indépendantes un journaliste doit-il recouper au minimum ?","aide":"C’est le minimum du recoupement.","type":"choix","options":[{"id":"a","texte":"Deux"},{"id":"b","texte":"Une"},{"id":"c","texte":"Aucune, s’il est expérimenté"},{"id":"d","texte":"Dix"}],"multiple":false}]}$ex$::jsonb,
