   $ex${"titre":"Ce que dit la loi","competence":"analyser-texte","situation":"Le professeur d’EMC distribue un extrait de loi adapté pour la classe. Il s’agit de repérer ce qui définit une discrimination.","documents":[{"id":"loi","type":"texte","genre":"source","titre":"Définition de la discrimination","blocs":["La discrimination est une différence de traitement défavorable, fondée sur un critère interdit par la loi, comme l’origine, le sexe ou le handicap.","Elle est punie de trois ans d’emprisonnement et de 45 000 € d’amende."],"source":"D’après le Code pénal, articles 225-1 et 225-2 (texte adapté pour l’exercice)."}],"questions":[{"enonce":"Touche les trois critères interdits cités dans le texte.","aide":"Ils suivent l’expression « comme l’ ».","type":"zone","document":"loi","multiple":true},{"enonce":"Pendant combien d’années de prison une discrimination est-elle punie au maximum ?","aide":"Lis la dernière phrase du texte.","type":"nombre","unite":"ans"},{"enonce":"Laquelle de ces situations est une discrimination ?","aide":"Il faut un traitement défavorable, un critère interdit et un domaine protégé.","type":"choix","options":[{"id":"a","texte":"Choisir un ami selon ses goûts"},{"id":"b","texte":"Ne pas inviter quelqu’un à son anniversaire"},{"id":"c","texte":"Refuser de louer un logement à quelqu’un à cause de son nom"},{"id":"d","texte":"Refuser un emploi à un candidat sans le diplôme exigé"}],"multiple":false}]}$ex$::jsonb,
