   $ex${"titre":"Directe, indirecte ou légitime ?","competence":"analyser-document","situation":"Une conseillère de la mission locale présente à des lycéens plusieurs cas tirés de situations réelles. Il faut les classer.","documents":[{"id":"cas","type":"tableau","titre":"Quatre situations","colonnes":["N°","La situation"],"lignes":[["1","Une entreprise écarte un candidat qui n’a pas le diplôme exigé pour le poste."],["2","Un propriétaire refuse de louer à une famille à cause de son nom."],["3","Un employeur refuse un candidat sans permis alors que le poste demande de conduire."],["4","Un club refuse une joueuse à cause de son handicap, alors que l’activité peut être adaptée."]],"enteteLignes":true,"source":"Cas imaginés pour l’exercice."},{"id":"reglement","type":"texte","genre":"consigne","titre":"Un règlement de recrutement","blocs":["« Pour devenir agent d’accueil, il faut mesurer au moins 1,80 m. » Cette taille n’a aucun lien avec les missions du poste, mais elle écarte surtout des femmes."],"source":"Règlement imaginé pour l’exercice."}],"questions":[{"enonce":"Classe chaque situation du tableau.","aide":"Un critère pertinent pour le poste est légitime ; un critère interdit non.","type":"categories","categories":[{"id":"c0","texte":"Discrimination"},{"id":"c1","texte":"Différence légitime"}],"items":[{"id":"i0","texte":"Situation 1"},{"id":"i1","texte":"Situation 3"},{"id":"i2","texte":"Situation 2"},{"id":"i3","texte":"Situation 4"}]},{"enonce":"Le règlement sur la taille minimale est une discrimination…","aide":"La règle est neutre en apparence, mais défavorise un groupe.","type":"choix","options":[{"id":"a","texte":"Inexistante"},{"id":"b","texte":"Directe"},{"id":"c","texte":"Indirecte"},{"id":"d","texte":"Légitime"}],"multiple":false},{"enonce":"Le recruteur dit : « Je n’ai pas voulu discriminer, ça m’est venu naturellement. » Est-ce une défense valable ?","aide":"Le droit juge le résultat de l’acte.","type":"choix","options":[{"id":"a","texte":"Oui, si c